/* DAWAH X — ahmad, অধ্যায় 122 · খণ্ড 122 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][122]=[[24201,24201,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رَجُلٌ ‏ ‏مِنْ أَهْلِ ‏ ‏الْكُوفَةِ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا خَرَجَ مِنْ مُغْتَسَلِهِ حَيْثُ يَغْتَسِلُ مِنْ الْجَنَابَةِ يَغْسِلُ قَدَمَيْهِ ‏","","",""],[24202,24202,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏مُغِيرَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَكَانُ الْكَيِّ التَّكْمِيدُ وَمَكَانُ ‏ ‏الْعِلَاقِ ‏ ‏السَّعُوطُ ‏ ‏وَمَكَانُ النَّفْخِ ‏ ‏اللَّدُودُ ‏","","",""],[24203,24203,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُغِيرَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏لَمَّا أَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏بَدْرٍ ‏ ‏بِأُولَئِكَ ‏ ‏الرَّهْطِ ‏ ‏فَأُلْقُوا فِي ‏ ‏الطُّوَى ‏ ‏عُتْبَةُ ‏ ‏وَأَبُو جَهْلٍ ‏ ‏وَأَصْحَابُهُ وَقَفَ عَلَيْهِمْ فَقَالَ ‏ ‏جَزَاكُمْ اللَّهُ شَرًّا مِنْ قَوْمِ نَبِيٍّ مَا كَانَ أَسْوَأَ الطَّرْدِ وَأَشَدَّ التَّكْذِيبِ قَالُوا يَا رَسُولَ اللَّهِ كَيْفَ تُكَلِّمُ قَوْمًا ‏ ‏جَيَّفُوا ‏ ‏فَقَالَ مَا أَنْتُمْ ‏ ‏بِأَفْهَمَ لِقَوْلِي مِنْهُمْ ‏ ‏أَوْ لَهُمْ أَفْهَمُ لِقَوْلِي مِنْكُمْ ‏","","",""],[24204,24204,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُغِيرَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُفْرِغُ يَمِينَهُ لِمَطْعَمِهِ وَلِحَاجَتِهِ وَيُفْرِغُ شِمَالَهُ ‏ ‏لِلِاسْتِنْجَاءِ وَلِمَا هُنَاكَ ‏","","",""],[24205,24205,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُغِيرَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا ‏ ‏كَانَتْ تَغْسِلُ رَأْسَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهِيَ حَائِضٌ وَهُوَ مُعْتَكِفٌ يُخْرِجُ رَأْسَهُ مِنْ الْمَسْجِدِ إِلَى الْحُجْرَةِ ‏","","",""],[24206,24206,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَتَّزِرُ وَأَنَا حَائِضٌ فَأَدْخُلُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِحَافَهُ ‏","","",""],[24207,24207,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُغِيرَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَدْ ‏ ‏خَيَّرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاخْتَرْنَاهُ فَلَمْ يَعُدَّ ذَلِكَ طَلَاقًا ‏","","",""],[24208,24208,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنَامُ وَهُوَ جُنُبٌ وَلَا يَمَسُّ مَاءً ‏","","",""],[24209,24209,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏مُرُوا أَزْوَاجَكُنَّ ‏ ‏أَنْ يَغْسِلُوا عَنْهُمْ أَثَرَ ‏ ‏الْغَائِطِ ‏ ‏وَالْبَوْلِ فَإِنِّي ‏ ‏أَسْتَحْيِيهِمْ وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَفْعَلُهُ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏مُرْنَ أَزْوَاجَكُنَّ ‏","","",""],[24210,24210,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي مَعْشَرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَنْ يَغْتَسِلَ بَدَأَ بِكَفَّيْهِ فَغَسَلَهُمَا ثُمَّ أَفَاضَ بِيَمِينِهِ عَلَى شِمَالِهِ فَغَسَلَ مَرَاقَّهُ حَتَّى إِذَا أَنْقَى أَهْوَى بِيَدِهِ إِلَى الْحَائِطِ ثُمَّ غَسَلَهَا ثُمَّ اسْتَقْبَلَ الطَّهُورَ وَأَفَاضَ عَلَيْهِ الْمَاءَ ‏","","",""],[24211,24211,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ الْعَدَوِيَّةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كُنْتُ أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْجَنَابَةِ مِنْ إِنَاءٍ وَاحِدٍ ‏","","",""],[24212,24212,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْجَنَابَةِ مِنْ إِنَاءٍ وَاحِدٍ ‏","","",""],[24213,24213,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏بُدَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي الْجَوْزَاءِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْتَتِحُ صَلَاتَهُ بِالتَّكْبِيرِ وَيَفْتَتِحُ الْقِرَاءَةَ بِ ‏ { ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏} ‏وَيَخْتِمُهَا بِالتَّسْلِيمِ ‏","","",""],[24214,24214,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِي مَعْشَرٍ ‏ ‏عَنِ ‏ ‏النَّخَعِيِّ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَبْعَثُ بِالْهَدْيِ فَنَفْتِلُ لَهَا قَلَائِدَهَا ثُمَّ لَا يُمْسِكُ عَنْ شَيْءٍ مِمَّا يُمْسِكُ عَنْهُ الْمُحْرِمُ ‏","","",""],[24215,24215,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏كَهْمَسٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ بُرَيْدَةَ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏يَا نَبِيَّ اللَّهِ أَرَأَيْتَ إِنْ وَافَقْتُ لَيْلَةَ الْقَدْرِ مَا أَقُولُ قَالَ تَقُولِينَ ‏ ‏اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي ‏","","",""],[24216,24216,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏كَهْمَسٌ ‏ ‏وَيَزِيدُ ‏ ‏قَالَ ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ الْمُقْرِيُّ ‏ ‏عَنْ ‏ ‏كَهْمَسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ شَقِيقٍ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏أَكَانَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي صَلَاةَ الضُّحَى قَالَتْ لَا إِلَّا أَنْ يَجِيءَ مِنْ ‏ ‏مَغِيبَةٍ ‏ ‏قَالَ قُلْتُ أَكَانَ ‏ ‏يُصَلِّي جَالِسًا قَالَتْ بَعْدَمَا حَطَمَهُ النَّاسُ قَالَ قُلْتُ أَكَانَ يَقْرَأُ السُّورَةَ فَقَالَتْ ‏ ‏الْمُفَصَّلَ ‏ ‏قَالَ قُلْتُ أَكَانَ يَصُومُ شَهْرًا كُلَّهُ قَالَتْ مَا عَلِمْتُهُ صَامَ شَهْرًا كُلَّهُ إِلَّا رَمَضَانَ وَلَا أَعْلَمُهُ أَفْطَرَ شَهْرًا كُلَّهُ حَتَّى يُصِيبَ مِنْهُ حَتَّى مَضَى لِوَجْهِهِ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏يَقْرِنُ ‏ ‏وَكَذَلِكَ قَالَ ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏","","",""],[24217,24217,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمِقْدَامَ بْنَ شُرَيْحِ بْنِ هَانِىءٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَ ‏ ‏رَكِبَتْ ‏ ‏عَائِشَةُ ‏ ‏بَعِيرًا وَكَانَ مِنْهُ صُعُوبَةٌ فَجَعَلَتْ تُرَدِّدُهُ فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْكِ بِالرِّفْقِ فَإِنَّهُ لَا يَكُ فِي شَيْءٍ إِلَّا زَانَهُ وَلَا يُنْزَعُ مِنْ شَيْءٍ إِلَّا شَانَهُ ‏","","",""],[24218,24218,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ فَيُبَادِرُنِي وَأُبَادِرُهُ حَتَّى ‏ ‏أَقُولَ دَعْ لِي دَعْ لِي ‏","","",""],[24219,24219,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ الرِّشْكِ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏أَنَّ امْرَأَةً سَأَلَتْ ‏ ‏عَائِشَةَ ‏ ‏هَلْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الضُّحَى قَالَ قَالَتْ نَعَمْ وَيُزِيدُ مَا شَاءَ اللَّهُ ‏","","",""],[24220,24220,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ الرِّشْكِ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏قَالَتْ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ الْغُسْلِ مِنْ الْجَنَابَةِ فَقَالَتْ ‏ ‏إِنَّ الْمَاءَ لَا يُنَجِّسُهُ شَيْءٌ قَدْ كُنْتُ أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ يَبْدَأُ فَيَغْسِلُ يَدَيْهِ ‏","","",""],[24221,24221,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏يَا أُمَّ الْمُؤْمِنِينَ أَخْبِرِينِي عَمَّا نَهَى عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْأَوْعِيَةِ قَالَتْ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالْمُزَفَّتِ ‏","","",""],[24222,24222,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ امْرَأَةً مُسْتَحَاضَةً سَأَلَتْ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقِيلَ إِنَّمَا هُوَ ‏ ‏عِرْقٌ ‏ ‏عَانِدٌ ‏ ‏وَأُمِرَتْ أَنْ تُؤَخِّرَ الظُّهْرَ وَتُعَجِّلَ الْعَصْرَ وَتَغْتَسِلَ غُسْلًا وَاحِدًا وَتُؤَخِّرَ الْمَغْرِبَ وَتُعَجِّلَ الْعِشَاءَ وَتَغْتَسِلَ لَهُمَا غُسْلًا وَاحِدًا وَتَغْتَسِلَ لِصَلَاةِ الصُّبْحِ غُسْلًا ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏غُسْلًا وَاحِدًا ‏","","",""],[24223,24223,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْقَاسِمَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏كَانَ لَهَا ثَوْبٌ فِيهِ تَصَاوِيرٌ مَمْدُودٌ إِلَى ‏ ‏سَهْوَةٍ ‏ ‏وَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي إِلَيْهَا فَقَالَ أَخِّرِيهِ عَنِّي قَالَتْ فَأَخَّرْتُهُ فَجَعَلْتُهُ وَسَائِدَ ‏","","",""],[24224,24224,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ الْقَاسِمِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْقَاسِمَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا ‏ ‏أَرَادَتْ أَنْ تَشْتَرِيَ ‏ ‏بَرِيرَةَ ‏ ‏لِلْعِتْقِ فَاشْتَرَطُوا ‏ ‏وَلَاءَهَا ‏ ‏فَذَكَرَتْ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏اشْتَرِيهَا وَأَعْتِقِيهَا فَإِنَّ ‏ ‏الْوَلَاءَ ‏ ‏لِمَنْ أَعْتَقَ وَأُهْدِيَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَحْمٌ فَقَالُوا لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا مَا تُصُدِّقَ بِهِ عَلَى ‏ ‏بَرِيرَةَ ‏ ‏فَقَالَ هُوَ لَهَا ‏ ‏صَدَقَةٌ ‏ ‏وَهُوَ لَنَا هَدِيَّةٌ وَخُيِّرَتْ ‏ ‏فَقَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَكَانَ زَوْجُهَا حُرًّا ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏ثُمَّ سَأَلْتُهُ عَنْ زَوْجِهَا فَقَالَ لَا أَدْرِي ‏","","",""],[24225,24225,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كُنْتُ أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ مِنْ الْجَنَابَةِ ‏","","",""],[24226,24226,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي مَعْشَرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ النَّخَعِيِّ ‏ ‏أَنَّهُ ‏ ‏كَانَ يَدْخُلُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏قَالَ قُلْتُ وَكَيْفَ كَانَ يَدْخُلُ عَلَيْهَا قَالَ كَانَ يَخْرُجُ مَعَ خَالِهِ ‏ ‏الْأَسْوَدِ ‏ ‏قَالَ وَكَانَ بَيْنَهُ وَبَيْنَ ‏ ‏عَائِشَةَ ‏ ‏إِخَاءٌ وَوُدٌّ ‏","","",""],[24227,24227,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏عَمَّتِهِ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا طَلَعَ الْفَجْرُ صَلَّى رَكْعَتَيْنِ ‏ ‏أَوْ لَمْ يُصَلِّ إِلَّا رَكْعَتَيْنِ ‏ ‏أَقُولُ يَقْرَأُ فِيهِمَا ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏","","",""],[24228,24228,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ عُرْفُطَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ خَيْرٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالْمُزَفَّتِ ‏","","",""],[24229,24229,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏مَا رَأَيْتُ الْوَجَعَ عَلَى أَحَدٍ أَشَدَّ مِنْهُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[24230,24230,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏خَيْثَمَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي عَطِيَّةَ ‏ ‏قَالَ قُلْنَا ‏ ‏لِعَائِشَةَ ‏ ‏إِنَّ فِينَا رَجُلَيْنِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَدُهُمَا يُعَجِّلُ الْإِفْطَارَ وَيُؤَخِّرُ السُّحُورَ وَالْآخَرُ يُؤَخِّرُ الْإِفْطَارَ وَيُعَجِّلُ السُّحُورَ قَالَ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏أَيُّهُمَا الَّذِي يُعَجِّلُ الْإِفْطَارَ وَيُؤَخِّرُ السُّحُورَ قَالَ فَقُلْتُ هُوَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَقَالَتْ كَذَا كَانَ يَصْنَعُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[24231,24231,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَمَّتِهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَلَدُ الرَّجُلِ مِنْ كَسْبِهِ مِنْ أَطْيَبِ كَسْبِهِ ‏","","",""],[24232,24232,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الضُّحَى ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏قَدْ خَيَّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِسَاءَهُ أَفَكَانَ طَلَاقًا ‏","","",""],[24233,24233,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏لَقَدْ رَأَيْتُ ‏ ‏وَبِيصَ ‏ ‏الطِّيبِ ‏ ‏فِي رَأْسِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُحْرِمٌ ‏","","",""],[24234,24234,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ مُسْلِمٍ يُشَاكُ شَوْكَةً فَمَا فَوْقَهَا إِلَّا رَفَعَهُ اللَّهُ بِهَا دَرَجَةً وَحَطَّ عَنْهُ بِهَا خَطِيئَةً ‏","","",""],[24235,24235,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏وَعَبْدِ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏الْمَعْنَى ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ عُبَيْدٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا ‏ ‏نَاوِلِينِي ‏ ‏الْخُمْرَةَ ‏ ‏قَالَتْ فَقُلْتُ إِنِّي حَائِضٌ فَقَالَ إِنَّهَا لَيْسَتْ فِي يَدِكِ فَنَاوَلْتُهُ ‏","","",""],[24236,24236,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏أَخْبَرَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا ‏ ‏كَانَتْ تَغْتَسِلُ هِيَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ ‏","","",""],[24237,24237,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مَيْمُونَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْأَحْوَصِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عُرْوَةَ بْنِ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَجُلًا مَرَّ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ ذُكِرَ رَجُلٌ عِنْدَهُ ‏ ‏فَقَالَ ‏ ‏بِئْسَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَأَخُو الْعَشِيرَةِ ثُمَّ دَخَلَ عَلَيْهِ فَأَقْبَلَ عَلَيْهِ بِوَجْهِهِ حَتَّى ظَنَنَّا أَنَّ لَهُ عِنْدَهُ مَنْزِلَةً ‏","","",""],[24238,24238,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏قَالَ ‏ ‏دَخَلَ نِسْوَةٌ مِنْ أَهْلِ ‏ ‏الشَّامِ ‏ ‏عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَقَالَتْ أَنْتُنَّ اللَّاتِي تَدْخُلْنَ الْحَمَّامَاتِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ امْرَأَةٍ وَضَعَتْ ثِيَابَهَا فِي غَيْرِ بَيْتِهَا إِلَّا هَتَكَتْ سِتْرًا بَيْنَهَا وَبَيْنَ اللَّهِ عَزَّ وَجَلَّ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏إِلَّا هَتَكَتْ سِتْرَهَا ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[24239,24239,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَلَمَةَ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَسَأَلْتُهَا عَنْ غُسْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْجَنَابَةِ قَالَتْ كَانَ ‏ ‏يُؤْتَى بِإِنَائِهِ فَيَغْسِلُ يَدَيْهِ ثَلَاثًا ثُمَّ يَصُبُّ مِنْ الْإِنَاءِ عَلَى فَرْجِهِ فَيَغْسِلُهُ ثُمَّ يُفْرِغُ بِيَدِهِ الْيُمْنَى عَلَى الْيُسْرَى فَيَغْسِلُهَا ثُمَّ يُمَضْمِضُ وَيَسْتَنْشِقُ ثُمَّ يُفْرِغُ عَلَى ‏ ‏رَأْسِهِ ثَلَاثًا ثُمَّ يَغْسِلُ سَائِرَ جَسَدِهِ ‏","","",""],[24240,24240,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُ إِحْدَانَا إِذَا حَاضَتْ ‏ ‏فَتَتَّزِرُ ‏ ‏ثُمَّ يُضَاجِعُهَا ‏ ‏قَالَ ‏ ‏هَذَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏ثُمَّ قَالَ بَعْدُ ‏ ‏ثُمَّ ‏ ‏يُبَاشِرُهَا ‏","","",""],[24241,24241,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَفْتِلُ ‏ ‏قَلَائِدَ ‏ ‏هَدْيِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَنَمًا ثُمَّ لَا يَحْرُمُ مِنْهُ شَيْءٌ ‏","","",""],[24242,24242,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَكُونُ بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي فَإِذَا أَرَدْتُ أَنْ أَقُومَ كَرِهْتُ أَنْ أَمُرَّ بَيْنَ يَدَيْهِ ‏ ‏فَأَنْسَلُّ ‏ ‏انْسِلَالًا ‏","","",""],[24243,24243,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ كَانَتْ ‏ ‏دِيمَةً ‏","","",""],[24244,24244,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُبَاشِرُ ‏ ‏وَهُوَ صَائِمٌ ‏","","",""],[24245,24245,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ نَافِعٍ ‏ ‏عَنْ ‏ ‏زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏لِعَائِشَةَ ‏ ‏إِنَّهُ يَدْخُلُ عَلَيْكِ الْغُلَامُ ‏ ‏الْأَيْفَعُ ‏ ‏الَّذِي مَا أُحِبُّ أَنْ يَدْخُلَ عَلَيَّ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏أَمَا لَكِ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ قَالَتْ ‏ ‏إِنَّ ‏ ‏امْرَأَةَ أَبِي حُذَيْفَةَ ‏ ‏قَالَتْ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏سَالِمًا ‏ ‏يَدْخُلُ عَلَيَّ وَهُوَ رَجُلٌ وَفِي نَفْسِ ‏ ‏أَبِي حُذَيْفَةَ ‏ ‏مِنْهُ شَيْءٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْضِعِيهِ حَتَّى يَدْخُلَ عَلَيْكِ ‏","","",""],[24246,24246,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْروِ بْنِ شُرَحْبِيلَ ‏ ‏عَنْ ‏ ‏أُمِّ الْمُؤْمِنِينَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُنَا إِذَا كَانَتْ إِحْدَانَا حَائِضًا أَنْ ‏ ‏تَتَّزِرَ ‏ ‏ثُمَّ تَدْخُلَ مَعَهُ فِي لِحَافِهِ ‏","","",""],[24247,24247,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الْجَدَلِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏لَمْ يَكُنْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاحِشًا ‏ ‏وَلَا ‏ ‏مُتَفَحِّشًا ‏ ‏وَلَا صَخَّابًا فِي الْأَسْوَاقِ وَلَا ‏ ‏يُجْزِي بِالسَّيِّئَةِ مِثْلَهَا وَلَكِنْ يَعْفُو وَيَصْفَحُ ‏","","",""],[24248,24248,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏أَشْعَثُ بْنُ سُلَيْمٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏يُحَدِّثُ ‏ ‏وَقَالَ ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏عَنِ ‏ ‏الْأَشْعَثِ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهَا وَعِنْدَهَا رَجُلٌ فَكَأَنَّهُ غَضِبَ فَقَالَتْ إِنَّهُ أَخِي قَالَ ‏ ‏انْظُرْنَ مَا إِخْوَانُكُنَّ فَإِنَّمَا الرَّضَاعَةُ مِنْ الْمَجَاعَةِ ‏","","",""],[24249,24249,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْأَشْعَثِ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ يَهُودِيَّةً دَخَلَتْ عَلَيْهَا فَذَكَرَتْ عَذَابَ الْقَبْرِ فَقَالَتْ لَهَا أَعَاذَكِ اللَّهُ مِنْ عَذَابِ الْقَبْرِ فَسَأَلَتْ ‏ ‏عَائِشَةُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ عَذَابِ الْقَبْرِ فَقَالَ نَعَمْ ‏ ‏عَذَابُ الْقَبْرِ حَقٌّ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَمَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي صَلَاةً بَعْدُ إِلَّا تَعَوَّذَ مِنْ عَذَابِ الْقَبْرِ ‏","","",""],[24250,24250,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏وَبَهْزٌ ‏ ‏أَخْبَرَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَصْبَهَانِيِّ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏: ‏ ‏ابْنُ وَرْدَانَ ‏ ‏وَقَالَ ‏ ‏حَجَّاجٌ ‏ ‏مُجَاهِدُ بْنُ وَرْدَانَ ‏ ‏مِنْ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏وَأَثْنَوْا عَلَيْهِ خَيْرًا ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏تُوُفِّيَ مَوْلًى لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِيرَاثِهِ فَقَالَ هَا هُنَا أَحَدٌ مِنْ أَهْلِ قَرْيَتِهِ قَالَ ‏ ‏بَهْزٌ ‏ ‏قَالُوا نَعَمْ قَالَ فَأَعْطُوهُ إِيَّاهُ ‏","","",""],[24251,24251,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُحَمَّدِ بْنِ الْمُنْتَشِرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَأَلَ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ الرَّجُلِ يَتَطَيَّبُ عِنْدَ إِحْرَامِهِ فَقَالَ لَأَنْ أَطَّلِيَ ‏ ‏بِقَطِرَانٍ ‏ ‏أَحَبُّ إِلَيَّ مِنْ أَنْ أَفْعَلَهُ قَالَ فَسَأَلَ أَبِي ‏ ‏عَائِشَةَ ‏ ‏وَأَخْبَرَهَا بِقَوْلِ ‏ ‏ابْنِ عُمَرَ ‏ ‏فَقَالَتْ يَرْحَمُ اللَّهُ ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏كُنْتُ أُطَيِّبُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ يَطُوفُ عَلَى نِسَائِهِ ثُمَّ يُصْبِحُ مُحْرِمًا يَنْتَضِحُ طِيبًا ‏","","",""],[24252,24252,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ الْأَيَّامَ الْمَعْلُومَةَ مِنْ الشَّهْرِ فَقَالَتْ نَعَمْ ‏","","",""],[24253,24253,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ ‏ ‏عَنْ ‏ ‏طَلْحَةَ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏ابْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا ‏ ‏سَأَلَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ ‏ ‏إِنَّ لِي جَارَيْنِ فَإِلَى أَيِّهِمَا أُهْدِي قَالَ أَقْرَبِهِمَا مِنْكِ بَابًا ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ ‏ ‏عَنْ ‏ ‏طَلْحَةَ ‏ ‏رَجُلٌ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏مِنْ ‏ ‏بَنِي تَيْمِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا سَأَلَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[24254,24254,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏سَمِعْتُ ‏ ‏عَلِيَّ بْنَ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏مَوْلَى ‏ ‏عَائِشَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَرْبَعٍ مَضَيْنَ مِنْ ذِي الْحِجَّةِ فَدَخَلَ عَلَيَّ وَهُوَ غَضْبَانُ فَقُلْتُ مَنْ أَغْضَبَكَ يَا رَسُولَ اللَّهِ أَدْخَلَهُ اللَّهُ النَّارَ فَقَالَ ‏ ‏وَمَا شَعَرْتِ أَنِّي أَمَرْتُ النَّاسَ بِأَمْرٍ فَأَرَاهُمْ يَتَرَدَّدُونَ ‏ ‏قَالَ ‏ ‏الْحَكَمُ ‏ ‏كَأَنَّهُمْ أَحْسَبُ ‏ ‏وَلَوْ أَنِّي اسْتَقْبَلْتُ مِنْ أَمْرِي مَا اسْتَدْبَرْتُ مَا سُقْتُ الْهَدْيَ مَعِي حَتَّى أَشْتَرِيَهُ ثُمَّ أَحِلَّ كَمَا أَحَلُّوا ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏يَتَرَدَّدُونَ فِيهِ قَالَ كَأَنَّهُمْ هَابُوا أَحْسَبُ ‏","","",""],[24255,24255,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا أَرَادَتْ أَنْ تَشْتَرِيَ ‏ ‏بَرِيرَةَ ‏ ‏لِلْعِتْقِ فَأَرَادَ ‏ ‏مَوَالِيهَا ‏ ‏أَنْ يَشْتَرِطُوا ‏ ‏وَلَاءَهَا ‏ ‏فَذَكَرَتْ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏اشْتَرِيهَا إِنَّمَا ‏ ‏الْوَلَاءُ ‏ ‏لِمَنْ أَعْتَقَ وَخَيَّرَهَا مِنْ زَوْجِهَا وَكَانَ زَوْجُهَا حُرًّا وَأُتِيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِلَحْمٍ فَقِيلَ هَذَا مَا تُصُدِّقَ بِهِ عَلَى ‏ ‏بَرِيرَةَ ‏ ‏فَقَالَ هُوَ لَهَا ‏ ‏صَدَقَةٌ ‏ ‏وَلَنَا هَدِيَّةٌ ‏","","",""],[24256,24256,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏إِبْرَاهِيمَ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَأَنَّمَا أَنْظُرُ إِلَى ‏ ‏وَبِيصِ ‏ ‏الطِّيبِ ‏ ‏فِي مَفْرِقِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُحْرِمٌ ‏","","",""],[24257,24257,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏لَمَّا أَرَادَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَنْفِرَ رَأَى ‏ ‏صَفِيَّةَ ‏ ‏عَلَى بَابِ ‏ ‏خِبَائِهَا ‏ ‏كَئِيبَةً أَوْ حَزِينَةً وَقَدْ حَاضَتْ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعَقْرَى ‏ ‏أَوْ حَلْقَى ‏ ‏إِنَّكِ ‏ ‏لَحَابِسَتُنَا ‏ ‏أَكُنْتِ أَفَضْتِ يَوْمَ النَّحْرِ قَالَتْ نَعَمْ قَالَ فَانْفِرِي إِذًا ‏","","",""],[24258,24258,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْروِ بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ مُسْلِمٍ يُشَاكُ شَوْكَةً فَمَا فَوْقَهَا إِلَّا رَفَعَهُ اللَّهُ عَزَّ وَجَلَّ بِهَا دَرَجَةً أَوْ حَطَّ بِهَا عَنْهُ خَطِيئَةً ‏","","",""],[24259,24259,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏ابْنُ عَوْفٍ ‏ ‏و حَدَّثَنَاه ‏ ‏يَعْقُوبُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏ابْنُ عَبْدِ اللَّهِ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏أَهْوَى ‏ ‏إِلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيُقَبِّلَنِي فَقُلْتُ إِنِّي صَائِمَةٌ قَالَ وَأَنَا صَائِمٌ فَقَبَّلَنِي ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏قَالَ لِي ‏ ‏سَعْدٌ ‏ ‏طَلْحَةُ ‏ ‏عَمُّ ‏ ‏أَبِي سَعْدٍ ‏","","",""],[24260,24260,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏أَخْبَرَنِي ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَلَمَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ أَيُّ الْعَمَلِ أَحَبُّ إِلَى اللَّهِ قَالَ أَدْوَمُهُ وَإِنْ قَلَّ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏مَا دُووِمَ عَلَيْهِ ‏ ‏وَقَالَ اكْلَفُوا مِنْ الْأَعْمَالِ مَا تُطِيقُونَ ‏","","",""],[24261,24261,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏أَخْبَرَنِي ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُرْوَةَ بْنَ الزُّبَيْرِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي وَأَنَا بَيْنَهُ وَبَيْنَ الْقِبْلَةِ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏سَعْدٌ ‏ ‏وَأَحْسَبُهُ قَدْ قَالَ وَهِيَ حَائِضٌ ‏","","",""],[24262,24262,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏وَرَوْحٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُرْوَةَ بْنَ الزُّبَيْرِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كُنْتُ أَسْمَعُ أَنَّهُ لَنْ يَمُوتَ نَبِيٌّ حَتَّى يُخَيَّرَ بَيْنَ الدُّنْيَا وَالْآخِرَةِ قَالَ فَسَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ وَأَخَذَتْهُ ‏ ‏بُحَّةٌ ‏ ‏يَقُولُ ‏ { ‏مَعَ الَّذِينَ أَنْعَمَ اللَّهُ عَلَيْهِمْ مِنْ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ وَحَسُنَ أُولَئِكَ رَفِيقًا ‏} ‏قَالَتْ فَظَنَنْتُ أَنَّهُ خُيِّرَ حِينَئِذٍ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏إِنَّهُ خُيِّرَ بَيْنَ الدُّنْيَا وَالْآخِرَةِ ‏","","",""],[24263,24263,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ فِي رُكُوعِهِ ‏ ‏سُبُّوحٌ قُدُّوسٌ رَبُّ الْمَلَائِكَةِ وَالرُّوحِ ‏","","",""],[24264,24264,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِاللَّيْلِ فَقَالَتْ كَانَ ‏ ‏يَنَامُ أَوَّلَ اللَّيْلِ ثُمَّ يَقُومُ فَإِذَا كَانَ مِنْ السَّحَرِ أَوْتَرَ ثُمَّ أَتَى فِرَاشَهُ فَإِنْ كَانَ لَهُ حَاجَةٌ أَلَمَّ بِأَهْلِهِ فَإِذَا سَمِعَ الْأَذَانَ وَثَبَ فَإِنْ كَانَ جُنُبًا أَفَاضَ عَلَيْهِ الْمَاءَ وَإِلَّا تَوَضَّأَ ثُمَّ خَرَجَ إِلَى الصَّلَاةِ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏أَبُو إِسْحَاقَ ‏ ‏أَخْبَرَنَا قَالَ سَمِعْتُ ‏ ‏الْأَسْوَدَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[24265,24265,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏وَمَسْرُوقٍ ‏ ‏أَنَّهُمَا قَالَا نَشْهَدُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏مَا كَانَ يَوْمُهُ الَّذِي يَكُونُ عِنْدِي إِلَّا ‏ ‏صَلَّاهُمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِي تَعْنِي الرَّكْعَتَيْنِ بَعْدَ الْعَصْرِ ‏","","",""],[24266,24266,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏لِلْأَسْوَدِ ‏ ‏حَدِّثْنِي عَنْ ‏ ‏أُمِّ الْمُؤْمِنِينَ عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏فَإِنَّهَا كَانَتْ ‏ ‏تُفْضِي إِلَيْكَ قَالَ أَخْبَرَتْنِي أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا ‏ ‏لَوْلَا أَنَّ قَوْمَكِ حَدِيثٌ عَهْدُهُمْ بِجَاهِلِيَّةٍ لَهَدَمْتُ ‏ ‏الْكَعْبَةَ ‏ ‏ثُمَّ لَجَعَلْتُ لَهَا بَابَيْنِ ‏ ‏فَلَمَّا مَلَكَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏هَدَمَهَا وَجَعَلَ لَهَا بَابَيْنِ ‏","","",""],[24267,24267,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ ‏ ‏أَحَبُّ الْعَمَلِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِي يَدُومُ عَلَيْهِ صَاحِبُهُ ‏","","",""],[24268,24268,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ مُحَمَّدِ بْنِ أَبِي بَكْرٍ الصِّدِّيقِ ‏ ‏أَخْبَرَ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَلَمْ تَرَيْ أَنَّ قَوْمَكِ حِينَ بَنَوْا ‏ ‏الْكَعْبَةَ ‏ ‏اقْتَصَرُوا ‏ ‏عَنْ قَوَاعِدِ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَالَتْ فَقُلْتُ يَا رَسُولَ اللَّهِ أَلَا تَرُدُّهَا عَلَى قَوَاعِدِ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا ‏ ‏حِدْثَانُ ‏ ‏قَوْمِكِ بِالْكُفْرِ ‏ ‏قَالَ فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏لَئِنْ كَانَتْ ‏ ‏عَائِشَةُ ‏ ‏سَمِعَتْ هَذَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أُرَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَرَكَ ‏ ‏اسْتِلَامَ ‏ ‏الرُّكْنَيْنِ اللَّذَيْنِ يَلِيَانِ الْحِجْرَ إِلَّا أَنَّ ‏ ‏الْبَيْتَ ‏ ‏لَمْ يَتِمَّ عَلَى قَوَاعِدِ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَلَيْهِ السَّلَام ‏","","",""],[24269,24269,"","","‏ ‏حَدَّثَنَا ‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏وَحَدَّثَنَاهُ ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَ حَجَّةِ الْوَدَاعِ ‏ ‏فَأَهْلَلْنَا ‏ ‏بِعُمْرَةٍ ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ مَعَهُ هَدْيٌ ‏ ‏فَلْيُهِلَّ ‏ ‏بِالْحَجِّ مَعَ الْعُمْرَةِ ثُمَّ لَا يَحِلُّ حَتَّى يَحِلَّ مِنْهُمَا جَمِيعًا قَالَتْ فَقَدِمْتُ ‏ ‏مَكَّةَ ‏ ‏وَأَنَا حَائِضٌ وَلَمْ أَطُفْ ‏ ‏بِالْبَيْتِ ‏ ‏وَلَا بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فَشَكَوْتُ ذَلِكَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏انْقُضِي ‏ ‏رَأْسَكِ وَامْتَشِطِي ‏ ‏وَأَهِلِّي ‏ ‏بِالْحَجِّ وَدَعِي الْعُمْرَةَ قَالَتْ فَفَعَلْتُ فَلَمَّا قَضَيْنَا الْحَجَّ أَرْسَلَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِى بَكْرٍ ‏ ‏إِلَى ‏ ‏التَّنْعِيمِ ‏ ‏فَاعْتَمَرْتُ فَقَالَ هَذِهِ مَكَانُ عُمْرَتِكِ قَالَتْ فَطَافَ الَّذِينَ ‏ ‏أَهَلُّوا ‏ ‏بِالْعُمْرَةِ ‏ ‏بِالْبَيْتِ ‏ ‏وَبَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏ثُمَّ حَلُّوا ثُمَّ طَافُوا طَوَافًا آخَرَ بَعْدَ أَنْ رَجَعُوا مِنْ ‏ ‏مِنًى ‏ ‏لِحَجِّهِمْ فَأَمَّا الَّذِينَ جَمَعُوا الْحَجَّ فَطَافُوا طَوَافًا وَاحِدًا ‏","","",""],[24270,24270,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَمْرَةَ بِنْتِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا ‏ ‏قَالَتْ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏صَفِيَّةَ بِنْتَ حُيَيٍّ ‏ ‏قَدْ حَاضَتْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَلَّهَا تَحْبِسُنَا ‏ ‏أَوَلَمْ تَكُنْ طَافَتْ مَعَكُنَّ ‏ ‏بِالْبَيْتِ ‏ ‏قَالُوا بَلَى قَالَ فَاخْرُجْنَ ‏","","",""],[24271,24271,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا أَخْبَرَتْهُ ‏ ‏أَنَّ ‏ ‏أَفْلَحَ ‏ ‏أَخَا ‏ ‏أَبِي الْقُعَيْسِ ‏ ‏جَاءَ يَسْتَأْذِنُ عَلَيْهَا وَهُوَ عَمُّهَا مِنْ الرَّضَاعَةِ بَعْدَ أَنْ نَزَلَ الْحِجَابُ قَالَتْ فَأَبَيْتُ أَنْ آذَنَ لَهُ فَلَمَّا جَاءَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرْتُهُ بِالَّذِي صَنَعْتُ فَأَمَرَنِي أَنْ آذَنَ لَهُ ‏","","",""],[24272,24272,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا كَانَتْ تَقُولُ ‏ ‏مَا كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسَبِّحُ سُبْحَةَ الضُّحَى وَإِنِّي لَأُسَبِّحُهَا ‏","","",""],[24273,24273,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏وحَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ أَبِي عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏أَهْدَى ‏ ‏أَبُو جَهْمِ بْنُ حُذَيْفَةَ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَمِيصَةً ‏ ‏شَامِيَّةً لَهَا ‏ ‏عَلَمٌ ‏ ‏فَشَهِدَ فِيهَا الصَّلَاةَ فَلَمَّا انْصَرَفَ قَالَ ‏ ‏رُدِّي هَذِهِ ‏ ‏الْخَمِيصَةَ ‏ ‏إِلَى ‏ ‏أَبِي جَهْمٍ ‏ ‏فَإِنِّي نَظَرْتُ إِلَى ‏ ‏عَلَمِهَا ‏ ‏فِي الصَّلَاةِ فَكَادَ يَفْتِنُنِي ‏","","",""],[24274,24274,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فِي الْمَسْجِدِ فَصَلَّى بِصَلَاتِهِ نَاسٌ ثُمَّ صَلَّى مِنْ الْقَابِلَةِ فَكَثُرَ النَّاسُ ثُمَّ اجْتَمَعُوا مِنْ اللَّيْلَةِ الثَّالِثَةِ ‏ ‏أَوْ الرَّابِعَةِ ‏ ‏فَلَمْ يَخْرُجْ إِلَيْهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا أَصْبَحَ قَالَ رَأَيْتُ الَّذِي صَنَعْتُمْ فَلَمْ يَمْنَعْنِي مِنْ الْخُرُوجِ إِلَيْكُمْ إِلَّا أَنِّي خَشِيتُ أَنْ تُفْرَضَ عَلَيْكُمْ وَذَلِكَ فِي رَمَضَانَ ‏","","",""],[24275,24275,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بِاللَّيْلِ ثَلَاثَ عَشْرَةَ رَكْعَةً ثُمَّ ‏ ‏يُصَلِّي إِذَا سَمِعَ النِّدَاءَ بِالصُّبْحِ رَكْعَتَيْنِ خَفِيفَتَيْنِ ‏","","",""],[24276,24276,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا أَخْبَرَتْهُ ‏ ‏أَنَّهَا لَمْ تَرَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي صَلَاةَ اللَّيْلِ قَاعِدًا حَتَّى أَسَنَّ فَكَانَ يَقْرَأُ قَاعِدًا حَتَّى إِذَا أَرَادَ أَنْ يَرْكَعَ قَامَ فَقَرَأَ نَحْوًا مِنْ ثَلَاثِينَ أَوْ أَرْبَعِينَ آيَةً ثُمَّ رَكَعَ ‏","","",""],[24277,24277,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏وَأَبِي النَّضْرِ ‏ ‏مَوْلَى ‏ ‏عُمَرَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي جَالِسًا فَيَقْرَأُ وَهُوَ جَالِسٌ فَإِذَا بَقِيَ عَلَيْهِ مِنْ قِرَاءَتِهِ قَدْرُ مَا يَكُونُ ثَلَاثِينَ أَوْ أَرْبَعِينَ آيَةً قَامَ فَقَرَأَ وَهُوَ قَائِمٌ ثُمَّ رَكَعَ ثُمَّ سَجَدَ ثُمَّ يَفْعَلُ فِي الرَّكْعَةِ الثَّانِيَةِ مِثْلَ ذَلِكَ ‏","","",""],[24278,24278,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنِ ‏ ‏الْقَعْقَاعِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي يُونُسَ ‏ ‏مَوْلَى ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَمَرَتْنِي ‏ ‏عَائِشَةُ ‏ ‏أَنْ أَكْتُبَ لَهَا مُصْحَفًا قَالَتْ إِذَا بَلَغْتَ هَذِهِ الْآيَةَ فَآذِنِّي ‏ { ‏حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلَاةِ الْوُسْطَى ‏} ‏قَالَ فَلَمَّا بَلَغْتُهَا آذَنْتُهَا فَأَمْلَتْ عَلَيَّ حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلَاةِ الْوُسْطَى وَصَلَاةِ الْعَصْرِ وَقُومُوا لِلَّهِ قَانِتِينَ ثُمَّ قَالَتْ سَمِعْتُهَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[24279,24279,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏مَا صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُبْحَةَ ‏ ‏الضُّحَى قَطُّ وَإِنِّي لَأُسَبِّحُهَا وَإِنْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَدَعُ الْعَمَلَ وَهُوَ يُحِبُّ أَنْ يَعْمَلَ بِهِ خَشْيَةَ أَنْ يَعْمَلَ بِهِ النَّاسُ فَيُفْرَضَ عَلَيْهِمْ ‏","","",""],[24280,24280,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏قَالَ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَتْ فِي ‏ ‏بَرِيرَةَ ‏ ‏ثَلَاثُ سُنَنٍ إِحْدَى السُّنَنِ الثَّلَاثِ أَنَّهَا عُتِقَتْ فَخُيِّرَتْ فِي زَوْجِهَا وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهَا ‏ ‏الْوَلَاءُ ‏ ‏لِمَنْ أَعْتَقَ وَدَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْبُرْمَةُ ‏ ‏تَفُورُ بِلَحْمٍ فَقُرِّبَ إِلَيْهِ خُبْزٌ ‏ ‏وَأُدْمٌ ‏ ‏مِنْ ‏ ‏أُدْمِ ‏ ‏الْبَيْتِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَمْ أَرَ ‏ ‏بُرْمَةً ‏ ‏فِيهَا لَحْمٌ فَقَالُوا بَلَى يَا رَسُولَ اللَّهِ وَلَكِنَّ ذَلِكَ لَحْمٌ تُصُدِّقَ بِهِ عَلَى ‏ ‏بَرِيرَةَ ‏ ‏وَأَنْتَ لَا تَأْكُلُ ‏ ‏الصَّدَقَةَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ لَهَا ‏ ‏صَدَقَةٌ ‏ ‏وَهُوَ لَنَا هَدِيَّةٌ ‏","","",""],[24281,24281,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ بِنْتِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ عِنْدَهَا وَأَنَّهَا سَمِعَتْ صَوْتَ رَجُلٍ يَسْتَأْذِنُ فِي بَيْتِ ‏ ‏حَفْصَةَ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ هَذَا رَجُلٌ يَسْتَأْذِنُ فِي بَيْتِكَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُرَاهُ فُلَانًا لِعَمٍّ ‏ ‏لِحَفْصَةَ ‏ ‏مِنْ الرَّضَاعَةِ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏يَا رَسُولَ اللَّهِ لَوْ كَانَ فُلَانٌ حَيًّا لِعَمِّهَا مِنْ الرَّضَاعَةِ أُدْخِلُ عَلَيَّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ ‏ ‏إِنَّ الرَّضَاعَةَ تُحَرِّمُ مَا تُحَرِّمُ الْوِلَادَةُ ‏","","",""],[24282,24282,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏عَمْرَةَ بِنْتِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏إِنْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيُصَلِّي الصُّبْحَ فَيَنْصَرِفُ النِّسَاءُ ‏ ‏مُتَلَفِّعَاتٌ ‏ ‏بِمُرُوطِهِنَّ ‏ ‏مَا يُعْرَفْنَ مِنْ ‏ ‏الْغَلَسِ ‏","","",""],[24283,24283,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ أَسْفَارِنَا حَتَّى إِذَا كُنَّا ‏ ‏بِالْبَيْدَاءِ ‏ ‏أَوْ ‏ ‏بِذَاتِ الْجَيْشِ ‏ ‏انْقَطَعَ عِقْدٌ لِي ‏ ‏فَأَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْتِمَاسِهِ وَأَقَامَ النَّاسُ مَعَهُ وَلَيْسُوا عَلَى مَاءٍ وَلَيْسَ مَعَهُمْ مَاءٌ فَأَتَى النَّاسُ إِلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏فَقَالُوا أَلَا ‏ ‏تَرَى مَا صَنَعَتْ ‏ ‏عَائِشَةُ ‏ ‏أَقَامَتْ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبِالنَّاسِ وَلَيْسُوا عَلَى مَاءٍ وَلَيْسَ مَعَهُمْ مَاءٌ فَجَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاضِعٌ رَأْسَهُ عَلَى فَخِذِي فَقَالَ ‏ ‏حَبَسْتِ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالنَّاسَ وَلَيْسُوا عَلَى مَاءٍ وَلَيْسَ مَعَهُمْ مَاءٌ قَالَتْ فَعَاتَبَنِي ‏ ‏أَبُو بَكْرٍ ‏ ‏وَقَالَ مَا شَاءَ اللَّهُ أَنْ يَقُولَ وَجَعَلَ يَطْعَنُ بِيَدِهِ فِي خَاصِرَتِي وَلَا يَمْنَعُنِي مِنْ التَّحَرُّكِ إِلَّا مَكَانُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى فَخِذِي فَنَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى أَصْبَحَ النَّاسُ عَلَى غَيْرِ مَاءٍ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏آيَةَ التَّيَمُّمِ ‏ ‏فَتَيَمَّمُوا فَقَالَ ‏ ‏أُسَيْدُ بْنُ الْحَضِيرِ ‏ ‏مَا هِيَ بِأَوَّلِ بَرَكَتِكُمْ يَا آلَ ‏ ‏أَبِي بَكْرٍ ‏ ‏قَالَتْ فَبَعَثْنَا الْبَعِيرَ الَّذِي كُنْتُ عَلَيْهِ فَوَجَدْنَا الْعِقْدَ تَحْتَهُ ‏","","",""],[24284,24284,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سَعْدٍ يَعْنِي ابْنَ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَبِّلُنِي وَهُوَ صَائِمٌ وَأَنَا صَائِمَةٌ ‏","","",""],[24285,24285,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏أَبِي عُذْرَةَ ‏ ‏وَكَانَ قَدْ أَدْرَكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى الرِّجَالَ وَالنِّسَاءَ عَنْ الْحَمَّامَاتِ ثُمَّ رَخَّصَ لِلرِّجَالِ فِي ‏ ‏الْمَيَازِرِ ‏","","",""],[24286,24286,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ مُحَمَّدِ بْنِ طَحْلَاءَ ‏ ‏عَنْ ‏ ‏أَبِي الرِّجَالِ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَائِشَةُ ‏ ‏بَيْتٌ لَيْسَ فِيهِ تَمْرٌ جِيَاعٌ أَهْلُهُ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏كَانَ ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَاهُ عَنْهُ ‏","","",""],[24287,24287,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنِ ‏ ‏الْأَزْرَقِ بْنِ قَيْسٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْأَزْرَقُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي عَلَى ‏ ‏الْخُمْرَةِ ‏","","",""],[24288,24288,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنِ ‏ ‏السُّدِّيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ الْبَهِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِلْجَارِيَةِ وَهُوَ فِي الْمَسْجِدِ ‏ ‏نَاوِلِينِي ‏ ‏الْخُمْرَةَ ‏ ‏قَالَتْ أَرَادَ أَنْ يَبْسُطَهَا فَيُصَلِّيَ عَلَيْهَا فَقَالَتْ إِنِّي حَائِضٌ فَقَالَ إِنَّ حَيْضَتَهَا لَيْسَتْ فِي يَدِهَا ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ السُّدِّيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ الْبَهِيِّ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏عَائِشَةُ ‏ ‏فَذَكَرَهُ ‏","","",""],[24289,24289,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنِ ‏ ‏السُّدِّيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ الْبَهِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا كُنْتُ أَقْضِي مَا يَبْقَى عَلَيَّ مِنْ رَمَضَانَ حَيَاةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلَّهَا إِلَّا فِي شَعْبَانَ ‏","","",""],[24290,24290,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ مِينَاءَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ الزُّبَيْرِ ‏ ‏يَقُولُ حَدَّثَتْنِي ‏ ‏خَالَتِي ‏ ‏عَائِشَةُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا ‏ ‏لَوْلَا أَنَّ قَوْمَكِ حَدِيثُ عَهْدٍ بِشِرْكٍ ‏ ‏أَوْ بِجَاهِلِيَّةٍ ‏ ‏لَهَدَمْتُ ‏ ‏الْكَعْبَةَ ‏ ‏فَأَلْزَقْتُهَا بِالْأَرْضِ وَجَعَلْتُ لَهَا بَابَيْنِ بَابًا شَرْقِيًّا وَبَابًا غَرْبِيًّا وَزِدْتُ فِيهَا مِنْ الْحَجَرِ سِتَّةَ أَذْرُعٍ فَإِنَّ ‏ ‏قُرِيْشًا ‏ ‏اقْتَصَرَتْهَا حِينَ بَنَتْ ‏ ‏الْكَعْبَةَ ‏","","",""],[24291,24291,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ امْرِئٍ يَكُونُ لَهُ صَلَاةٌ مِنْ اللَّيْلِ يَغْلِبُهُ عَلَيْهَا نَوْمٌ إِلَّا كَانَ نَوْمُهُ عَلَيْهِ ‏ ‏صَدَقَةً ‏ ‏وَكُتِبَ لَهُ أَجْرُ صَلَاتِهِ ‏","","",""],[24292,24292,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ بِنْتِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَفْتِلُ ‏ ‏قَلَائِدَ ‏ ‏هَدْيِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدَيَّ ثُمَّ ‏ ‏يُقَلِّدُهَا ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ ثُمَّ يَبْعَثُ بِهَا مَعَ أَبِي فَلَا يَدَعُ شَيْئًا أَحَلَّهُ اللَّهُ عَزَّ وَجَلَّ لَهُ حَتَّى يَنْحَرَ ‏ ‏الْهَدْيَ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏خَالَتِهِ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنَّ قَوْمَكِ حَدِيثٌ عَهْدُهُمْ بِالشِّرْكِ لَهَدَمْتُ ‏ ‏الْكَعْبَةَ ‏ ‏فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏ابْنِ مَهْدِيٍّ ‏","","",""],[24293,24293,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا مَاتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى ‏ ‏أُحِلَّ ‏ ‏لَهُ النِّسَاءُ ‏","","",""],[24294,24294,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَائِشَةَ أُمَّ الْمُؤْمِنِينَ ‏ ‏تَقُولُ ‏ ‏إِنَّ ‏ ‏بَرِيرَةَ ‏ ‏كَانَتْ ‏ ‏مُكَاتِبَةً ‏ ‏لِأُنَاسٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَأَرَدْتُ أَنْ أَبْتَاعَهَا فَأَمَرْتُهَا أَنْ تَأْتِيَهُمْ فَتُخْبِرَهُمْ أَنِّي أُرِيدُ أَنْ أَبْتَاعَهَا فَأُعْتِقَهَا فَقَالُوا إِنْ جَعَلْتِ لَنَا ‏ ‏وَلَاءَهَا ‏ ‏ابْتَعْنَاهَا مِنْهَا فَاسْتَفْتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏اشْتَرِيهَا فَأَعْتِقِيهَا فَإِنَّمَا ‏ ‏الْوَلَاءُ ‏ ‏لِمَنْ أَعْتَقَ وَدَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْمِرْجَلُ ‏ ‏يَفُورُ بِلَحْمٍ فَقَالَ مِنْ أَيْنَ لَكِ هَذَا قُلْتُ أَهْدَتْهُ لَنَا ‏ ‏بَرِيرَةُ ‏ ‏وَتُصُدِّقَ بِهِ عَلَيْهَا فَقَالَ هَذَا ‏ ‏لبَرِيرَةَ ‏ ‏صَدَقَةٌ ‏ ‏وَلَنَا هَدِيَّةٌ قَالَتْ وَكَانَتْ تَحْتَ عَبْدٍ فَلَمَّا أَعْتَقَهَا قَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اخْتَارِي فَإِنْ شِئْتِ أَنْ تَمْكُثِي تَحْتَ هَذَا الْعَبْدِ وَإِنْ شِئْتِ أَنْ تُفَارِقِيهِ ‏","","",""],[24295,24295,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزُ بْنُ أَسَدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِي فِي ‏ ‏إِزَارٍ ‏ ‏وَرِدَاءٍ فَاسْتَقْبَلَ الْقِبْلَةَ وَبَسَطَ يَدَهُ وَقَالَ ‏ ‏اللَّهُمَّ إِنَّمَا أَنَا بَشَرٌ فَأَيُّ عَبْدٍ مِنْ عِبَادِكَ ضَرَبْتُ أَوْ آذَيْتُ فَلَا تُعَاقِبْنِي فِيهِ ‏","","",""],[24296,24296,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَسُبُّوا الْأَمْوَاتَ فَإِنَّهُمْ قَدْ أَفْضَوْا إِلَى مَا قَدَّمُوا ‏","","",""],[24297,24297,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وحَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏شَرِيكِ بْنِ نَمِرٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْرُجُ إِذَا كَانَتْ لَيْلَةُ ‏ ‏عَائِشَةَ ‏ ‏إِذَا ذَهَبَ ثُلُثَا اللَّيْلِ إِلَى ‏ ‏الْبَقِيعِ ‏ ‏فَيَقُولُ ‏ ‏السَّلَامُ عَلَيْكُمْ أَهْلَ دَارِ قَوْمٍ مُؤْمِنِينَ فَإِنَّا وَإِيَّاكُمْ وَمَا تُوعَدُونَ غَدًا مُؤَجَّلُونَ ‏ ‏قَالَ ‏ ‏أَبُو عَامِرٍ ‏ ‏تُؤَجَّلُونَ ‏ ‏وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ ‏","","",""],[24298,24298,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏سَمِعَ ‏ ‏الْقَاسِمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ عَمِلَ عَمَلًا لَيْسَ عَلَيْهِ أَمْرُنَا فَهُوَ رَدٌّ ‏","","",""],[24299,24299,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الْأَعْمَالِ أَحَبُّ إِلَى اللَّهِ عَزَّ وَجَلَّ قَالَ أَدْوَمُهُ وَإِنْ قَلَّ ‏ ‏قَالَ ‏ ‏وَسَمِعْتُهُ ‏ ‏يَعْنِي ‏ ‏أَبَا سَلَمَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اكْلَفُوا ‏ ‏مِنْ الْعَمَلِ مَا تُطِيقُونَ ‏","","",""],[24300,24300,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَقِيلُو ‏ ‏ذَوِي ‏ ‏الْهَيْئَاتِ ‏ ‏عَثَرَاتِهِمْ ‏ ‏إِلَّا ‏ ‏الْحُدُودَ ‏","","",""],[24301,24301,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَامَ فِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏وَالَّذِي لَا إِلَهَ غَيْرُهُ لَا يَحِلُّ دَمُ رَجُلٍ مُسْلِمٍ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي ‏ ‏مُحَمَّدٌ ‏ ‏رَسُولُ اللَّهِ إِلَّا ثَلَاثَةَ نَفَرٍ التَّارِكُ الْإِسْلَامَ وَالْمُفَارِقُ الْجَمَاعَةَ ‏ ‏وَالثَّيِّبُ ‏ ‏الزَّانِي وَالنَّفْسُ بِالنَّفْسِ ‏ ‏قَالَ ‏ ‏الْأَعْمَشُ ‏ ‏فَحَدَّثْتُ بِهِ ‏ ‏إِبْرَاهِيمَ ‏ ‏فَحَدَّثَنِي عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏بِمِثْلِهِ ‏","","",""],[24302,24302,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏طَيَّبْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِحُرْمِهِ حِينَ أَحْرَمَ ‏ ‏وَلِحِلِّهِ ‏ ‏حِينَ ‏ ‏أَحَلَّ ‏ ‏قَبْلَ أَنْ يَطُوفَ ‏ ‏بِالْبَيْتِ ‏","","",""],[24303,24303,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ غَالِبٍ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لِلْأَشْتَرِ ‏ ‏أَنْتَ الَّذِي أَرَدْتَ قَتْلَ ابْنِ أُخْتِي قَالَ قَدْ حَرَصْتُ عَلَى قَتْلِهِ وَحَرَصَ عَلَى قَتْلِي قَالَتْ أَوَمَا عَلِمْتَ مَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَحِلُّ دَمُ رَجُلٍ إِلَّا رَجُلٌ ارْتَدَّ أَوْ تَرَكَ الْإِسْلَامَ أَوْ زَنَى بَعْدَمَا أُحْصِنَ أَوْ قَتَلَ نَفْسًا بِغَيْرِ نَفْسٍ ‏","","",""],[24304,24304,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَصْبَهَانِيِّ ‏ ‏عَنْ ‏ ‏مُجَاهِدِ بْنِ وَرْدَانَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏مَوْلًى ‏ ‏لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَّ ‏ ‏مِنْ ‏ ‏عَذْقِ ‏ ‏نَخْلَةٍ فَمَاتَ فَأُتِيَ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ هَلْ لَهُ مِنْ نَسَبٍ أَوْ رَحِمٍ قَالُوا لَا قَالَ ‏ ‏أَعْطُوا مِيرَاثَهُ بَعْضَ أَهْلِ قَرْيَتِهِ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏ابْنِ الْأَصْبَهَانِيِّ ‏ ‏عَنْ ‏ ‏مُجَاهِدِ بْنِ وَرْدَانَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏فَدَفَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِيرَاثَهُ إِلَى أَهْلِ قَرْيَتِهِ ‏","","",""],[24305,24305,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏أَبِي عَطِيَّةَ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏خَيْثَمَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي عَطِيَّةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِنِّي لَأَعْلَمُ كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُلَبِّي ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏ثُمَّ سَمِعْتُهَا بَعْدُ لَبَّتْ ‏","","",""],[24306,24306,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا رَأَيْتُ إِنْسَانًا قَطُّ أَشَدَّ عَلَيْهِ الْوَجَعُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[24307,24307,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏رَخَّصَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ الْأَمْرِ فَرَغِبَ عَنْهُ رِجَالٌ فَقَالَ ‏ ‏مَا بَالُ رِجَالٍ آمُرُهُمْ الْأَمْرَ يَرْغَبُونَ عَنْهُ وَاللَّهِ إِنِّي لَأَعْلَمُهُمْ بِاللَّهِ عَزَّ وَجَلَّ وَأَشَدُّهُمْ لَهُ خَشْيَةً ‏","","",""],[24308,24308,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏إِذَا مَرِضَ يَقْرَأُ عَلَى نَفْسِهِ ‏ ‏بِالْمُعَوِّذَاتِ ‏ ‏وَيَنْفُثُ ‏","","",""],[24309,24309,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا اعْتَكَفَ يُدْنِي إِلَيَّ رَأْسَهُ أُرَجِّلُهُ وَكَانَ لَا يَدْخُلُ بَيْتَهُ إِلَّا لِحَاجَةِ الْإِنْسَانِ ‏","","",""],[24310,24310,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا خُيِّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ أَمْرَيْنِ إِلَّا اخْتَارَ أَيْسَرَهُمَا مَا لَمْ يَكُنْ فِيهِ إِثْمٌ فَإِذَا كَانَ فِيهِ إِثْمٌ كَانَ أَبْعَدَ النَّاسِ مِنْهُ وَمَا انْتَقَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِنَفْسِهِ مِنْ شَيْءٍ يُؤْتَى إِلَيْهِ إِلَّا أَنْ ‏ ‏تُنْتَهَكَ ‏ ‏حُرْمَةُ اللَّهِ فَيَنْتَقِمَ لِلَّهِ عَزَّ وَجَلَّ ‏","","",""],[24311,24311,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ إِحْدَى عَشْرَةَ رَكْعَةً يُوتِرُ مِنْهَا بِوَاحِدَةٍ فَإِذَا فَرَغَ مِنْ صَلَاتِهِ اضْطَجَعَ عَلَى شِقِّهِ الْأَيْمَنِ ‏","","",""],[24312,24312,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏يَا ‏ ‏أُمَّهْ ‏ ‏بِأَيِّ شَيْءٍ كَانَ يَبْدَأُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ عَلَيْكِ بَيْتَكِ وَبِأَيِّ شَيْءٍ كَانَ يَخْتِمُ قَالَتْ كَانَ يَبْدَأُ بِالسِّوَاكِ وَيَخْتِمُ بِرَكْعَتَيْ الْفَجْرِ ‏","","",""],[24313,24313,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَابَقْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَبَقْتُهُ ‏","","",""],[24314,24314,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَنَامُ مُعْتَرِضَةً بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي فَإِذَا أَرَادَ أَنْ يُوتِرَ ‏ ‏غَمَزَنِي ‏ ‏بِرِجْلِهِ فَقَالَ تَنَحَّيْ ‏","","",""],[24315,24315,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا ‏ ‏أُمَّهْ كَيْفَ كَانَتْ صَلَاةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ الْعِشَاءِ الْآخِرَةِ قَالَتْ كَانَ ‏ ‏يُصَلِّي ثَلَاثَ عَشْرَةَ رَكْعَةً تِسْعًا قَائِمًا وَثِنْتَيْنِ جَالِسًا وَثِنْتَيْنِ بَعْدَ النِّدَاءَيْنِ ‏ ‏يَعْنِي بَيْنَ أَذَانِ الْفَجْرِ وَبَيْنَ الْإِقَامَةِ ‏","","",""],[24316,24316,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَقَدْ ‏ ‏كَانَ يَأْتِي عَلَى آلِ ‏ ‏مُحَمَّدٍ ‏ ‏الشَّهْرُ مَا يُرَى فِي بَيْتٍ مِنْ بُيُوتِهِ الدُّخَانُ قُلْتُ يَا ‏ ‏أُمَّهْ وَمَا كَانَ طَعَامُهُمْ قَالَتْ الْأَسْوَدَانِ التَّمْرُ وَالْمَاءُ غَيْرَ أَنَّهُ كَانَ لَهُ جِيرَانُ صِدْقٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَكَانَ لَهُمْ ‏ ‏رَبَائِبُ ‏ ‏فَكَانُوا يَبْعَثُونَ إِلَيْهِ مِنْ أَلْبَانِهَا ‏","","",""],[24317,24317,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي وَجَعِهِ الَّذِي مَاتَ فِيهِ مَا فَعَلَتْ الذَّهَبُ قَالَتْ قُلْتُ وَهِيَ عِنْدِي قَالَ ائْتِينِي بِهَا فَجِئْتُ بِهَا وَهِيَ مَا بَيْنَ التِّسْعِ ‏ ‏أَوْ الْخَمْسِ ‏ ‏فَوَضَعَهَا فِي يَدِهِ ثُمَّ قَالَ بِهَا ‏ ‏وَأَشَارَ ‏ ‏يَزِيدُ ‏ ‏بِيَدِهِ ‏ ‏مَا ظَنُّ ‏ ‏مُحَمَّدٍ ‏ ‏بِاللَّهِ لَوْ لَقِيَ اللَّهَ عَزَّ وَجَلَّ وَهَذِهِ عِنْدَهُ أَنْفِقِيهَا ‏","","",""],[24318,24318,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي مَيْسَرَةَ ‏ ‏قَالَ قَالَتْ ‏ ‏أُمُّ الْمُؤْمِنِينَ عَائِشَةُ ‏ ‏إِنْ كُنْتُ لَأَتَّزِرُ ثُمَّ أَدْخُلُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي لِحَافِهِ وَأَنَا حَائِضٌ ‏","","",""],[24319,24319,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَجْنُبُ ثُمَّ يَنَامُ فَإِذَا قَامَ اغْتَسَلَ وَخَرَجَ وَرَأْسُهُ يَقْطُرُ ثُمَّ يَصُومُ بَقِيَّةَ ذَلِكَ الْيَوْمِ ‏","","",""],[24320,24320,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏يَا رَسُولَ اللَّهِ إِنْ وَافَقْتُ لَيْلَةَ الْقَدْرِ فَبِمَ أَدْعُو قَالَ قُولِي ‏ ‏اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي ‏","","",""],[24321,24321,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنَا ‏ ‏سُفْيَانُ يَعْنِي ابْنَ حُسَيْنٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏نَزَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى فِي الْمَسْجِدِ ذَاتَ لَيْلَةٍ فِي رَمَضَانَ وَصَلَّى خَلْفَهُ نَاسٌ بِصَلَاتِهِ ثُمَّ نَزَلَ اللَّيْلَةَ الثَّانِيَةَ فَكَانُوا أَكْثَرَ مِنْ ذَلِكَ ثُمَّ كَثُرُوا فِي اللَّيْلَةِ الثَّالِثَةِ فَلَمَّا كَانَتْ اللَّيْلَةُ الرَّابِعَةُ ‏ ‏غَصَّ ‏ ‏الْمَسْجِدُ بِأَهْلِهِ فَلَمْ يَنْزِلْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا فِي ذَلِكَ مَا شَأْنُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَنْزِلْ فَسَمِعَ مَقَالَتَهُمْ فَلَمَّا أَصْبَحَ قَالَ يَا أَيُّهَا النَّاسُ ‏ ‏إِنِّي قَدْ سَمِعْتُ مَقَالَتَكُمْ وَإِنَّهُ لَمْ يَمْنَعْنِي أَنْ أَنْزِلَ إِلَيْكُمْ إِلَّا مَخَافَةَ أَنْ يُفْتَرَضَ عَلَيْكُمْ قِيَامُ هَذَا الشَّهْرِ ‏","","",""],[24322,24322,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏كَهْمَسٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏يَا رَسُولَ اللَّهِ إِنْ وَافَقْتُ لَيْلَةَ الْقَدْرِ بِمَ أَدْعُو قَالَ قُولِي ‏ ‏اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي ‏","","",""],[24323,24323,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَفْتِلُ ‏ ‏قَلَائِدَ ‏ ‏هَدْيِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَبْعَثُ بِهَا وَلَا يَدَعُ شَيْئًا مِمَّا كَانَ يَصْنَعُ قَبْلَ ذَلِكَ ‏","","",""],[24324,24324,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الثَّقَفِيُّ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏سُئِلَتْ عَنْ رَكْعَتَيْ الْفَجْرِ فَقَالَتْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُخَفِّفُهُمَا قَالَتْ فَأَظُنُّهُ كَانَ يَقْرَأُ بِنَحْوٍ مِنْ ‏ ‏قُلْ يَا أَيُّهَا الْكَافِرُونَ ‏ ‏وَقُلْ هُوَ اللَّهُ أَحَدٌ ‏","","",""],[24325,24325,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الثَّقَفِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏أَنَّهُ قَالَ مَا اسْتَقْبَلْتُ الْقِبْلَةَ بِفَرْجِي مُنْذُ كَذَا وَكَذَا ‏ ‏فَحَدَّثَ ‏ ‏عِرَاكُ بْنُ مَالِكٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ ‏ ‏بِخَلَائِهِ ‏ ‏أَنْ يُسْتَقْبَلَ بِهِ الْقِبْلَةَ لَمَّا بَلَغَهُ أَنَّ النَّاسَ يَكْرَهُونَ ذَلِكَ ‏","","",""],[24326,24326,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الثَّقَفِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصْبِحُ جُنُبًا مِنْ غَيْرِ احْتِلَامٍ ثُمَّ يَصُومُ ‏","","",""],[24327,24327,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ يَعْنِي أَبَا الْعَلَاءِ الْقَصَّابَ ‏ ‏عَنْ ‏ ‏أَبِي هَاشِمٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي جَالِسًا فَإِذَا أَرَادَ الرُّكُوعَ قَامَ فَقَرَأَ قَدْرَ عَشْرِ آيَاتٍ أَوْ مَا شَاءَ اللَّهُ ثُمَّ رَكَعَ ‏","","",""],[24328,24328,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بُرْدٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ بَابُنَا فِي قِبْلَةِ الْمَسْجِدِ فَاسْتَفْتَحْتُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فَمَشَى حَتَّى فَتَحَ لِي ثُمَّ رَجَعَ إِلَى مَكَانِهِ الَّذِي كَانَ فِيهِ ‏","","",""],[24329,24329,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏أَخْبَرَنِي ‏ ‏سُفْيَانُ بْنُ حُسَيْنٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ شَرْطٍ لَيْسَ فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ فَهُوَ مَرْدُودٌ وَإِنْ اشْتَرَطُوا مِائَةَ مَرَّةٍ ‏","","",""],[24330,24330,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَرَأَيْتَ لَوْ أَنِّي عَلِمْتُ لَيْلَةَ الْقَدْرِ مَا كُنْتُ أَدْعُو بِهِ رَبِّي عَزَّ وَجَلَّ ‏ ‏أَوْ مَا كُنْتُ أَسْأَلُهُ ‏ ‏قَالَ قُولِي ‏ ‏اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي ‏","","",""],[24331,24331,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَنْظَلَةُ السَّدُوسِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ نَوْفَلٍ ‏ ‏قَالَ ‏ ‏صَلَّى ‏ ‏مُعَاوِيَةُ ‏ ‏بِالنَّاسِ الْعَصْرَ فَالْتَفَتَ فَإِذَا أُنَاسٌ يُصَلُّونَ بَعْدَ الْعَصْرِ فَدَخَلَ وَدَخَلَ عَلَيْهِ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏وَأَنَا مَعَهُ فَأَوْسَعَ لَهُ ‏ ‏مُعَاوِيَةُ ‏ ‏عَلَى السَّرِيرِ فَجَلَسَ مَعَهُ قَالَ مَا هَذِهِ الصَّلَاةُ الَّتِي رَأَيْتُ النَّاسَ يُصَلُّونَهَا وَلَمْ أَرَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّيهَا وَلَا أَمَرَ بِهَا قَالَ ذَاكَ مَا ‏ ‏يُفْتِيهِمْ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏فَدَخَلَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏فَسَلَّمَ فَجَلَسَ فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏يَا ‏ ‏ابْنَ الزُّبَيْرِ ‏ ‏مَا هَذِهِ الصَّلَاةُ الَّتِي تَأْمُرُ النَّاسَ يُصَلُّونَهَا لَمْ نَرَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّاهَا وَلَا أَمَرَ بِهَا قَالَ حَدَّثَتْنِي ‏ ‏عَائِشَةُ أُمُّ الْمُؤْمِنِينَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّاهَا عِنْدَهَا فِي بَيْتِهَا قَالَ فَأَمَرَنِي ‏ ‏مُعَاوِيَةُ ‏ ‏وَرَجُلٌ آخَرُ أَنْ نَأْتِيَ ‏ ‏عَائِشَةَ ‏ ‏فَنَسْأَلَهَا عَنْ ذَلِكَ قَالَ ‏ ‏فَدَخَلْتُ عَلَيْهَا فَسَأَلْتُهَا عَنْ ذَلِكَ فَأَخْبَرْتُهَا بِمَا أَخْبَرَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏عَنْهَا فَقَالَتْ لَمْ يَحْفَظْ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏إِنَّمَا حَدَّثْتُهُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى هَذِهِ الرَّكْعَتَيْنِ بَعْدَ الْعَصْرِ عِنْدِي فَسَأَلْتُهُ قُلْتُ إِنَّكَ صَلَّيْتَ رَكْعَتَيْنِ لَمْ تَكُنْ تُصَلِّيهِمَا قَالَ إِنَّهُ كَانَ أَتَانِي شَيْءٌ فَشُغِلْتُ فِي قِسْمَتِهِ عَنْ الرَّكْعَتَيْنِ بَعْدَ الظُّهْرِ وَأَتَانِي ‏ ‏بِلَالٌ ‏ ‏فَنَادَانِي بِالصَّلَاةِ فَكَرِهْتُ أَنْ أَحْبِسَ النَّاسَ فَصَلَّيْتُهُمَا ‏ ‏قَالَ ‏ ‏فَرَجَعْتُ فَأَخْبَرْتُ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏أَلَيْسَ قَدْ صَلَّاهُمَا فَلَا نَدَعُهُمَا فَقَالَ لَهُ ‏ ‏مُعَاوِيَةُ ‏ ‏لَا تَزَالُ مُخَالِفًا أَبَدًا ‏","","",""],[24332,24332,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏عَنِ ‏ ‏الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا سَلَّمَ مِنْ الصَّلَاةِ قَالَ ‏ ‏اللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ ‏","","",""],[24333,24333,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكْثِرُ أَنْ يَقُولَ قَبْلَ مَوْتِهِ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ قَالَتْ وَكَانَ يُكْثِرُ أَنْ يَقُولَهُ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّكَ تَدْعُو بِدُعَاءٍ لَمْ تَكُنْ تَدْعُو بِهِ قَبْلَ الْيَوْمِ فَقَالَ إِنَّ رَبِّي عَزَّ وَجَلَّ أَخْبَرَنِي أَنِّي ‏ ‏سَأَرَى عَلَمًا فِي أُمَّتِي وَأَنِّي إِذَا رَأَيْتُ ذَلِكَ الْعَلَمَ أَنْ أُسَبِّحَ بِحَمْدِهِ وَأَسْتَغْفِرَهُ فَقَدْ رَأَيْتُ ذَلِكَ ‏ { ‏إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا ‏}","","",""],[24334,24334,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَتَّابٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏يَقُولُ مَنْ أَصْبَحَ جُنُبًا فَلَا صَوْمَ لَهُ قَالَ فَأَرْسَلَنِي ‏ ‏مَرْوَانُ بْنُ الْحَكَمِ ‏ ‏أَنَا وَرَجُلًا آخَرَ إِلَى ‏ ‏عَائِشَةَ ‏ ‏وَأُمِّ سَلَمَةَ ‏ ‏نَسْأَلُهُمَا عَنْ ‏ ‏الْجُنُبِ ‏ ‏يُصْبِحُ فِي رَمَضَانَ قَبْلَ أَنْ يَغْتَسِلَ قَالَ فَقَالَتْ إِحْدَاهُمَا قَدْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصْبِحُ جُنُبًا ثُمَّ يَغْتَسِلُ وَيُتِمُّ صِيَامَ يَوْمِهِ قَالَ وَقَالَتْ الْأُخْرَى كَانَ يُصْبِحُ جُنُبًا مِنْ غَيْرِ أَنْ يَحْتَلِمَ ثُمَّ يُتِمُّ صَوْمَهُ قَالَ فَرَجَعَا فَأَخْبَرَا ‏ ‏مَرْوَانَ ‏ ‏بِذَلِكَ فَقَالَ ‏ ‏لِعَبْدِ الرَّحْمَنِ ‏ ‏أَخْبِرْ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏بِمَا قَالَتَا ‏ ‏فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏كَذَا كُنْتُ أَحْسَبُ وَكَذَا كُنْتُ أَظُنُّ قَالَ فَقَالَ لَهُ ‏ ‏مَرْوَانُ ‏ ‏بِأَظُنُّ ‏ ‏وَبِأَحْسَبُ ‏ ‏تُفْتِي النَّاسَ ‏","","",""],[24335,24335,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏وَهِشَامٍ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقْرَأُ فِي رَكْعَتَيْ الْفَجْرِ ‏ ‏بِقُلْ يَا أَيُّهَا الْكَافِرُونَ ‏ ‏وَقُلْ هُوَ اللَّهُ أَحَدٌ ‏ ‏قَالَ ‏ ‏و حَدَّثَنَا ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏يَعْنِي ‏ ‏عَلِيًّا ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسِرُّ بِهِمَا ‏","","",""],[24336,24336,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏قَالَ ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏أَخْبَرَنِي عَنْ ‏ ‏خَالِدِ بْنِ أَبِي الصَّلْتِ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏فِي خِلَافَتِهِ قَالَ وَعِنْدَهُ ‏ ‏عِرَاكُ بْنُ مَالِكٍ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏مَا اسْتَقْبَلْتُ الْقِبْلَةَ وَلَا اسْتَدْبَرْتُهَا بِبَوْلٍ وَلَا ‏ ‏غَائِطٍ ‏ ‏مُنْذُ كَذَا وَكَذَا ‏ ‏فَقَالَ ‏ ‏عِرَاكٌ ‏ ‏حَدَّثَتْنِي ‏ ‏عَائِشَةُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا بَلَغَهُ قَوْلُ النَّاسِ فِي ذَلِكَ ‏ ‏أَمَرَ بِمَقْعَدَتِهِ فَاسْتَقْبَلَ بِهَا الْقِبْلَةَ ‏","","",""],[24337,24337,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَدْ كَانَتْ ‏ ‏تَخْرُجُ ‏ ‏الْكِعَابُ ‏ ‏مِنْ ‏ ‏خِدْرِهَا ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْعِيدَيْنِ ‏","","",""],[24338,24338,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏صَفِيَّةَ ‏ ‏تَقُولُ قَالَتْ ‏ ‏عَائِشَةُ زَوْجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ ‏ ‏حَفْصَةُ ‏ ‏أَوْ هُمَا ‏ ‏تَقُولَانِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَحِلُّ لِامْرَأَةٍ تُؤْمِنُ بِاللَّهِ أَنْ ‏ ‏تُحِدَّ ‏ ‏فَوْقَ ثَلَاثَةِ أَيَّامٍ إِلَّا عَلَى زَوْجِهَا ‏","","",""],[24339,24339,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ عَبْدِ الرَّحْمَنِ الْقُرَشِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏حِضْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى فِرَاشِهِ ‏ ‏فَانْسَلَلْتُ ‏ ‏فَقَالَ لِي أَحِضْتِ فَقُلْتُ نَعَمْ قَالَ ‏ ‏فَشُدِّي عَلَيْكِ ‏ ‏إِزَارَكَ ‏ ‏ثُمَّ عُودِي ‏","","",""],[24340,24340,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ حَمْزَةَ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبَّادَ بْنَ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أُمَّ الْمُؤْمِنِينَ عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْحِسَابِ الْيَسِيرِ فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏مَا الْحِسَابُ الْيَسِيرُ فَقَالَ الرَّجُلُ تُعْرَضُ عَلَيْهِ ذُنُوبُهُ ثُمَّ يُتَجَاوَزُ لَهُ عَنْهَا إِنَّهُ مَنْ نُوقِشَ الْحِسَابَ هَلَكَ وَلَا يُصِيبُ عَبْدًا شَوْكَةٌ فَمَا فَوْقَهَا إِلَّا قَاصَّ اللَّهُ عَزَّ وَجَلَّ بِهَا مِنْ خَطَايَاهُ ‏","","",""],[24341,24341,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَنَّ ‏ ‏عُرْوَةَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهُ قَالَتْ ‏ ‏لَقَدْ كُنْتُ ‏ ‏أَفْتِلُ ‏ ‏قَلَائِدَ ‏ ‏هَدْيِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ يَبْعَثُ بِهِ وَيُقِيمُ فَمَا يَتَّقِي مِنْ شَيْءٍ ‏","","",""],[24342,24342,"","","‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ بُرْقَانَ ‏ ‏قَالَ سَأَلْتُ ‏ ‏الزُّهْرِيَّ ‏ ‏عَنْ الرَّجُلِ يُخَيِّرُ امْرَأَتَهُ فَتَخْتَارُهُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَتَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنِّي سَأَعْرِضُ عَلَيْكِ أَمْرًا فَلَا عَلَيْكِ أَنْ لَا تَعْجَلِي فِيهِ حَتَّى تُشَاوِرِي أَبَوَيْكِ فَقُلْتُ وَمَا هَذَا الْأَمْرُ قَالَتْ فَتَلَا عَلَيَّ ‏ { ‏يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ إِنْ كُنْتُنَّ تُرِدْنَ الْحَيَاةَ الدُّنْيَا وَزِينَتَهَا فَتَعَالَيْنَ أُمَتِّعْكُنَّ ‏ ‏وَأُسَرِّحْكُنَّ ‏ ‏سَرَاحًا جَمِيلًا وَإِنْ كُنْتُنَّ تُرِدْنَ اللَّهَ وَرَسُولَهُ وَالدَّارَ الْآخِرَةَ فَإِنَّ اللَّهَ أَعَدَّ لِلْمُحْسِنَاتِ مِنْكُنَّ أَجْرًا عَظِيمًا ‏} ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَقُلْتُ وَفِي أَيِّ ذَلِكَ تَأْمُرُنِي أُشَاوِرُ أَبَوَيَّ بَلْ أُرِيدُ اللَّهَ وَرَسُولَهُ وَالدَّارَ الْآخِرَةَ قَالَتْ فَسُرَّ بِذَلِكَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَعْجَبَهُ وَقَالَ سَأَعْرِضُ عَلَى صَوَاحِبِكِ مَا عَرَضْتُ عَلَيْكِ قَالَتْ فَقُلْتُ لَهُ فَلَا تُخْبِرْهُنَّ بِالَّذِي اخْتَرْتُ فَلَمْ يَفْعَلْ وَكَانَ يَقُولُ لَهُنَّ كَمَا قَالَ ‏ ‏لِعَائِشَةَ ‏ ‏ثُمَّ يَقُولُ قَدْ اخْتَارَتْ ‏ ‏عَائِشَةُ ‏ ‏اللَّهَ وَرَسُولَهُ وَالدَّارَ الْآخِرَةَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏قَدْ خَيَّرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ نَرَ ذَلِكَ طَلَاقًا ‏","","",""],[24343,24343,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عِمْرَانَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ حَاضَتْ ‏ ‏صَفِيَّةُ بِنْتُ حُيَيٍّ ‏ ‏وَهِيَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِنًى ‏ ‏بَعْدَ أَنْ ‏ ‏أَفَاضَتْ ‏ ‏قَالَتْ فَلَمَّا كَانَ يَوْمُ ‏ ‏النَّفْرِ ‏ ‏ذُكِرَ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَسَى أَنْ تَحْبِسَنَا قَالَ فَقِيلَ يَا رَسُولَ اللَّهِ إِنَّهَا قَدْ كَانَتْ طَافَتْ ‏ ‏بِالْبَيْتِ ‏ ‏قَالَ ‏ ‏فَلْتَنْفِرْ ‏","","",""],[24344,24344,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا تَرَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دِينَارًا وَلَا دِرْهَمًا وَلَا أَمَةً وَلَا عَبْدًا وَلَا شَاةً وَلَا بَعِيرًا ‏","","",""],[24345,24345,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ الرِّشْكِ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏أَنَّ امْرَأَةً سَأَلَتْ ‏ ‏عَائِشَةَ ‏ ‏أَتُجْزِئُ الْحَائِضُ الصَّلَاةَ قَالَتْ ‏ ‏أَحَرُورِيَّةٌ ‏ ‏أَنْتِ ‏ ‏قَدْ حِضْنَ نِسَاءُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفَأَمَرَهُنَّ أَنْ يَجْزِينَ ‏","","",""],[24346,24346,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏أَيُّ سَاعَةٍ تُوتِرِينَ لَعَلَّهُ قَالَتْ مَا ‏ ‏أُوتِرُ ‏ ‏حَتَّى يُؤَذِّنُونَ وَمَا يُؤَذِّنُونَ حَتَّى يَطْلُعَ الْفَجْرُ قَالَتْ وَكَانَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُؤَذِّنَانِ ‏ ‏بِلَالٌ ‏ ‏وَعَمْرُو ابْنُ أُمِّ مَكْتُومٍ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَذَّنَ ‏ ‏عَمْرٌو ‏ ‏فَكُلُوا وَاشْرَبُوا فَإِنَّهُ رَجُلٌ ‏ ‏ضَرِيرُ ‏ ‏الْبَصَرِ وَإِذَا أَذَّنَ ‏ ‏بِلَالٌ ‏ ‏فَارْفَعُوا أَيْدِيَكُمْ فَإِنَّ ‏ ‏بِلَالًا ‏ ‏لَا يُؤَذِّنُ ‏ ‏كَذَا قَالَ ‏ ‏حَتَّى يُصْبِحَ ‏","","",""],[24347,24347,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَأَنِّي أَنْظُرُ إِلَى ‏ ‏وَبِيصِ ‏ ‏الطِّيبِ فِي مَفْرِقِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ أَيَّامٍ وَهُوَ مُحْرِمٌ ‏","","",""],[24348,24348,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏طَيَّبْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِطِيبٍ فِيهِ مِسْكٌ عِنْدَ إِحْرَامِهِ قَبْلَ أَنْ يُحْرِمَ وَيَوْمَ ‏ ‏النَّحْرِ ‏ ‏قَبْلَ أَنْ يَطُوفَ ‏ ‏بِالْبَيْتِ ‏","","",""],[24349,24349,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْقَاسِمِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كُنْتُ ‏ ‏أُطَيِّبُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِحُرْمِهِ حِينَ يُحْرِمُ ‏ ‏وَلِحِلِّهِ ‏ ‏حِينَ ‏ ‏يُحِلُّ ‏ ‏قَبْلَ أَنْ يَطُوفَ ‏ ‏بِالْبَيْتِ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏وصَخْرٌ ‏ ‏وَحَمَّادٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏بِمِثْلِهِ إِلَّا أَنَّهُمْ قَالُوا لِحُرْمِهِ قَبْلَ أَنْ يُحْرِمَ ‏","","",""],[24350,24350,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ مَنْصُورٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْقَاسِمَ بْنَ مُحَمَّدٍ ‏ ‏وَيُوسُفَ بْنَ مَاهَكَ ‏ ‏وَعَطَاءً ‏ ‏يَذْكُرُونَ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كُنْتُ ‏ ‏أُطَيِّبُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ إِحْلَالِهِ وَعِنْدَ إِحْرَامِهِ ‏","","",""],[24351,24351,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَأَنِّي أَنْظُرُ إِلَى ‏ ‏وَبِيصِ ‏ ‏الطِّيبِ ‏ ‏فِي مَفْرِقِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُحْرِمٌ ‏","","",""],[24352,24352,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَأَنِّي أَنْظُرُ إِلَى ‏ ‏وَبِيصِ ‏ ‏الطِّيبِ ‏ ‏فِي مَفْرِقِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ أَيَّامٍ وَهُوَ مُحْرِمٌ ‏","","",""],[24353,24353,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ أَخِي عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَمَّتِهِ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الرَّكْعَتَيْنِ قَبْلَ ‏ ‏الْغَدَاةِ ‏ ‏فَيُخَفِّفُهُمَا حَتَّى إِنِّي لَأَشُكُّ أَقَرَأَ فِيهِمَا ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏ ‏أَمْ لَا ‏","","",""],[24354,24354,"","","‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ حَفْصٍ أَبُو حَفْصٍ الْمُعَيْطِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا تَكْتَنِينَ قَالَتْ بِمَنْ ‏ ‏أَكْتَنِي قَالَ اكْتَنِي بِابْنِكِ ‏ ‏عَبْدِ اللَّهِ يَعْنِي ابْنَ الزُّبَيْرِ ‏ ‏قَالَ فَكَانَتْ ‏ ‏تُكَنَّى ‏ ‏بِأُمِّ عَبْدِ اللَّهِ ‏","","",""],[24355,24355,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ وَلَدِ ‏ ‏الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏كُلُّ نِسَائِكَ لَهَا كُنْيَةٌ غَيْرِي قَالَ أَنْتِ ‏ ‏أُمُّ عَبْدِ اللَّهِ ‏","","",""],[24356,24356,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا نَزَلَتْ ‏ ‏آيَاتُ الرِّبَا ‏ ‏قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ فَتَلَاهُنَّ عَلَى النَّاسِ ثُمَّ ‏ ‏حَرَّمَ التِّجَارَةَ فِي الْخَمْرِ ‏","","",""],[24357,24357,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْوَلَاءُ ‏ ‏لِمَنْ أَعْطَى ‏ ‏الْوَرِقَ ‏ ‏وَأَعْتَقَ وَوَلِيِّ النِّعْمَةِ وَكَانَ زَوْجُهَا حُرًّا فَخُيِّرَتْ ‏","","",""],[24358,24358,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَتْ ‏ ‏الْحَبَشَةُ ‏ ‏يَلْعَبُونَ يَوْمَ عِيدٍ فَدَعَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكُنْتُ أَطَّلِعُ مِنْ ‏ ‏عَاتِقِهِ ‏ ‏فَأَنْظُرُ إِلَيْهِمْ فَجَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعْهَا ‏ ‏فَإِنَّ لِكُلِّ قَوْمٍ عِيدًا وَهَذَا عِيدُنَا ‏","","",""],[24359,24359,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏وَأَنْذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ ‏} ‏قَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ‏ ‏فَاطِمَةُ بِنْتُ مُحَمَّدٍ ‏ ‏يَا ‏ ‏صَفِيَّةُ بِنْتُ عَبْدِ الْمُطَّلِبِ ‏ ‏يَا ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏لَا أَمْلِكُ لَكُمْ مِنْ اللَّهِ شَيْئًا سَلُونِي مِنْ مَالِي مَا شِئْتُمْ ‏","","",""],[24360,24360,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ الْجَوْنِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏يُقَالُ لَهُ ‏ ‏طَلْحَةُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قُلْتُ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ لِي جَارَيْنِ إِلَى أَيِّهِمَا أُهْدِي قَالَ إِلَى أَقْرَبِهِمَا بَابًا مِنْكِ ‏","","",""],[24361,24361,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏زُهَيْرٍ ‏ ‏عَنْ ‏ ‏عَمْرٍو يَعْنِي ابْنَ أَبِي عَمْرٍو ‏ ‏وَمَوْلَى ‏ ‏الْمُطَّلِبِ ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ يَعْنِي ابْنَ حَنْطَبٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الرَّجُلَ لَيُدْرِكُ بِحُسْنِ خُلُقِهِ دَرَجَةَ الصَّائِمِ الْقَائِمِ ‏","","",""],[24362,24362,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا تَرَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دِينَارًا وَلَا دِرْهَمًا وَلَا شَاةً وَلَا بَعِيرًا ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏عُلِمْنَ وَأَشُكُّ فِي الْعَبْدِ وَالْأَمَةِ ‏","","",""],[24363,24363,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏زُبَيْدٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا زَالَ ‏ ‏جِبْرِيلُ ‏ ‏يُوصِينِي بِالْجَارِ حَتَّى ظَنَنْتُ أَنَّهُ مُوَرِّثُهُ ‏","","",""],[24364,24364,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَابِسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَقُلْتُ لَهَا أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْ لُحُومِ الْأَضَاحِيِّ بَعْدَ ثَلَاثٍ فَقَالَتْ نَعَمْ أَصَابَ النَّاسَ شِدَّةٌ فَأَحَبَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُطْعِمَ الْغَنِيُّ الْفَقِيرَ ثُمَّ لَقَدْ رَأَيْتُ آلَ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْكُلُونَ ‏ ‏الْكُرَاعَ ‏ ‏بَعْدَ خَمْسَ عَشْرَةَ فَقُلْتُ لَهَا مِمَّ ذَاكَ قَالَ فَضَحِكَتْ وَقَالَتْ مَا شَبِعَ آلُ ‏ ‏مُحَمَّدٍ ‏ ‏مِنْ خُبْزٍ ‏ ‏مَأْدُومٍ ‏ ‏ثَلَاثَةَ أَيَّامٍ حَتَّى لَحِقَ اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[24365,24365,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏وَزَيْدُ بْنُ الْحُبَابِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏إِسْرَائِيلُ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُهَاجِرٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مَاهَكَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَلَا نَبْنِي لَكَ ‏ ‏بِمِنًى ‏ ‏بَيْتًا أَوْ بِنَاءً يُظِلُّكَ مِنْ الشَّمْسِ فَقَالَ لَا إِنَّمَا هُوَ ‏ ‏مُنَاخُ ‏ ‏مَنْ ‏ ‏سَبَقَ إِلَيْهِ ‏","","",""],[24366,24366,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ الْجَوْنِيِّ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ بَابَنُوسَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَشَّحُنِي وَيَنَالُ مِنْ رَأْسِي وَأَنَا حَائِضٌ ‏","","",""],[24367,24367,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏وَكَانَتْ إِحْدَانَا تَحِيضُ وَتَطْهُرُ فَلَا يَأْمُرُنَا بِقَضَاءٍ وَلَا ‏ ‏نَقْضِيهِ ‏","","",""],[24368,24368,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ سَعْدٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏وَأَبُو كَامِلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏جَاءَتْ ‏ ‏أُمُّ حَبِيبَةَ بِنْتُ جَحْشٍ ‏ ‏قَالَ ‏ ‏أَبُو كَامِلٍ ‏ ‏أُمُّ حَبِيبٍ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَتْ ‏ ‏اسْتُحِيضَتْ ‏ ‏سَبْعَ سِنِينَ فَاشْتَكَتْ ذَلِكَ إِلَيْهِ وَاسْتَفْتَتْهُ فِيهِ فَقَالَ لَيْسَ هَذَا بِالْحَيْضَةِ وَلَكِنَّ هَذَا ‏ ‏عِرْقٌ ‏ ‏فَاغْتَسِلِي وَصَلِّي فَكَانَتْ تَغْتَسِلُ لِكُلِّ صَلَاةٍ وَتُصَلِّي وَكَانَتْ تَجْلِسُ فِي ‏ ‏مِرْكَنٍ ‏ ‏فَتَعْلُو حُمْرَةُ الدَّمِ الْمَاءَ ثُمَّ تُصَلِّي ‏","","",""],[24369,24369,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَشْعَثَ بْنِ أَبِي الشَّعْثَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ ‏ ‏التَّيَمُّنُ ‏ ‏فِي شَأْنِهِ كُلِّهِ فِي ‏ ‏تَرَجُّلِهِ ‏ ‏وَفِي طُهُورِهِ وَفِي نَعْلِهِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏ثُمَّ سَأَلْتُهُ بَعْدَ ذَلِكَ فَقَالَ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ ‏ ‏أَوْ يُعْجِبُهُ ‏ ‏التَّيَمُّنُ ‏ ‏مَا اسْتَطَاعَ ‏","","",""],[24370,24370,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَيْسٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ الرَّكْعَتَيْنِ بَعْدَ الْعَصْرِ فَقَالَتْ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي رَكْعَتَيْنِ بَعْدَ الظُّهْرِ فَشُغِلَ عَنْهُمَا حَتَّى صَلَّى الْعَصْرَ فَلَمَّا فَرَغَ رَكَعَهُمَا فِي بَيْتِي فَمَا تَرَكَهُمَا حَتَّى مَاتَ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي قَيْسٍ ‏ ‏فَسَأَلْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَنْهُ قَالَ ‏ ‏قَدْ كُنَّا نَفْعَلُهُ ثُمَّ تَرَكْنَاهُ ‏","","",""],[24371,24371,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏عَنْ ‏ ‏أَبِي الزَّاهِرِيَّةِ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَقَالَتْ هَلْ تَقْرَأُ سُورَةَ ‏ ‏الْمَائِدَةِ ‏ ‏قَالَ قُلْتُ نَعَمْ قَالَتْ فَإِنَّهَا آخِرُ سُورَةٍ نَزَلَتْ فَمَا وَجَدْتُمْ فِيهَا مِنْ حَلَالٍ فَاسْتَحِلُّوهُ وَمَا وَجَدْتُمْ فِيهَا مِنْ حَرَامٍ فَحَرِّمُوهُ ‏ ‏وَسَأَلْتُهَا عَنْ خُلُقِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ الْقُرْآنُ ‏","","",""],[24372,24372,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَيْسٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏كَانَ ‏ ‏أَحَبُّ الشُّهُورِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَصُومَهُ شَعْبَانَ ثُمَّ يَصِلَهُ بِرَمَضَانَ ‏","","",""],[24373,24373,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَعْقُوبُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي الرِّجَالِ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَائِشَةُ ‏ ‏بَيْتٌ لَيْسَ فِيهِ تَمْرٌ جِيَاعٌ أَهْلُهُ ‏","","",""],[24374,24374,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ اجْعَلْنِي مِنْ الَّذِينَ إِذَا أَحْسَنُوا اسْتَبْشَرُوا وَإِذَا أَسَاءُوا اسْتَغْفَرُوا ‏","","",""],[24375,24375,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُهَاجِرٍ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏ذُكِرَتْ نِسَاءُ ‏ ‏الْأَنْصَارِ ‏ ‏فَأَثْنَتْ عَلَيْهِنَّ وَقَالَتْ لَهُنَّ مَعْرُوفًا وَقَالَتْ لَمَّا نَزَلَتْ سُورَةُ ‏ ‏النُّورِ ‏ ‏عَمَدْنَ إِلَى ‏ ‏حُجَزِ ‏ ‏أَوْ ‏ ‏حُجُوزِ ‏ ‏مَنَاطِقِهِنَّ فَشَقَقْنَهُ ثُمَّ اتَّخَذْنَ مِنْهُ ‏ ‏خُمُرًا ‏ ‏وَأَنَّهَا دَخَلَتْ ‏ ‏امْرَأَةٌ ‏ ‏مِنْهُنَّ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ أَخْبِرْنِي عَنْ الطُّهُورِ مِنْ الْمَحِيضِ فَقَالَ نَعَمْ ‏ ‏لِتَأْخُذْ إِحْدَاكُنَّ مَاءَهَا ‏ ‏وَسِدْرَتَهَا ‏ ‏فَلْتَطَّهَّرْ ثُمَّ لِتُحْسِنْ الطُّهُورَ ثُمَّ تَصُبَّ عَلَى رَأْسِهَا ثُمَّ ‏ ‏لِتُلْزِقْ ‏ ‏بِشُؤُونِ رَأْسِهَا ثُمَّ تَدْلُكْهُ فَإِنَّ ذَلِكَ طُهُورٌ ثُمَّ تَصُبَّ عَلَيْهَا مِنْ الْمَاءِ ثُمَّ تَأْخُذْ ‏ ‏فِرْصَةً ‏ ‏مُمَسَّكَةً ‏ ‏فَلْتَطَّهَّرْ بِهَا قَالَتْ يَا رَسُولَ اللَّهِ كَيْفَ أَتَطَهَّرُ بِهَا فَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكْنِي عَنْ ذَلِكَ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏تَتْبَعُ بِهَا أَثَرَ الدَّمِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏ثُمَّ لِتَصُبَّ عَلَى رَأْسِهَا مِنْ الْمَاءِ وَلْتُلْصِقْ شُؤُونَ رَأْسِهَا فَلْتَدْلُكْهُ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏إِلَى ‏ ‏حُجَزٍ ‏ ‏أَوْ ‏ ‏حُجُوزٍ ‏","","",""],[24376,24376,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏صَدَقَةَ ‏ ‏رَجُلٍ مِنْ أَهْلِ ‏ ‏الْكُوفَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جُمَيْعُ بْنُ عُمَيْرٍ ‏ ‏أَحَدُ ‏ ‏بَنِي تَيْمِ اللَّهِ ابْنِ ثَعْلَبَةَ ‏ ‏قَالَ ‏ ‏دَخَلْتُ مَعَ أُمِّي وَخَالَتِي عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَسَأَلَتْ إِحْدَاهُمَا كَيْفَ كُنْتُنَّ تَصْنَعْنَ عِنْدَ الْغُسْلِ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ وُضُوءَهُ لِلصَّلَاةِ ثُمَّ يُفِيضُ عَلَى رَأْسِهِ ثَلَاثَ مَرَّاتٍ وَنَحْنُ نُفِيضُ عَلَى رُءُوسِنَا خَمْسًا مِنْ أَجْلِ ‏ ‏الضَّفْرِ ‏","","",""],[24377,24377,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ بَيْتَهُ بَدَأَ بِالسِّوَاكِ ‏","","",""],[24378,24378,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ شَيْبَانَ ‏ ‏عَنْ ‏ ‏أَبِي نَوْفَلٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُتَسَامَعُ عِنْدَهُ الشِّعْرُ فَقَالَتْ قَدْ كَانَ أَبْغَضَ الْحَدِيثِ إِلَيْهِ ‏","","",""],[24379,24379,"","","‏ ‏وَقَالَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ ‏ ‏الْجَوَامِعُ ‏ ‏مِنْ الدُّعَاءِ وَيَدَعُ مَا بَيْنَ ذَلِكَ ‏","","",""],[24380,24380,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏مَرْوَانَ أَبِي لُبَابَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ حَتَّى نَقُولَ مَا يُرِيدُ أَنْ يُفْطِرَ وَيُفْطِرُ حَتَّى نَقُولَ مَا يُرِيدُ أَنْ يَصُومَ وَكَانَ يَقْرَأُ كُلَّ لَيْلَةٍ ‏ ‏بِبَنِي إِسْرَائِيلَ ‏ ‏وَالزُّمَرِ ‏","","",""],[24381,24381,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا خُيِّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ أَمْرَيْنِ قَطُّ إِلَّا ‏ ‏اخْتَارَ أَيْسَرَهُمَا إِلَّا أَنْ يَكُونَ فِيهِ إِثْمٌ فَإِنْ كَانَ إِثْمًا كَانَ أَبْعَدَ النَّاسِ مِنْهُ ‏","","",""],[24382,24382,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو أَبُو عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏حَدَّثَتْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَكُنْ يَصُومُ مِنْ شَهْرٍ مِنْ السَّنَةِ أَكْثَرَ مِنْ صَوْمِهِ مِنْ شَعْبَانَ فَإِنَّهُ كَانَ يَصُومُ شَعْبَانَ كُلَّهُ وَكَانَ يَقُولُ ‏ ‏خُذُوا مِنْ الْعَمَلِ مَا تُطِيقُونَ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَا ‏ ‏يَمَلُّ ‏ ‏حَتَّى ‏ ‏تَمَلُّوا ‏ ‏وَإِنَّهُ كَانَ أَحَبُّ الصَّلَاةِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا دُووِمَ عَلَيْهَا وَكَانَ إِذَا صَلَّى صَلَاةً دَاوَمَ عَلَيْهَا ‏","","",""],[24383,24383,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏وَيَزِيدُ ‏ ‏قَالَا أَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّيْلَ قَالَتْ كَانَ ‏ ‏يُصَلِّي ثَلَاثَ عَشْرَةَ رَكْعَةً ‏ ‏يُصَلِّي ‏ ‏ثَمَانِيَ رَكَعَاتٍ ثُمَّ ‏ ‏يُوتِرُ ‏ ‏ثُمَّ ‏ ‏يُصَلِّي رَكْعَتَيْنِ وَهُوَ جَالِسٌ فَإِذَا أَرَادَ أَنْ يَرْكَعَ قَامَ فَرَكَعَ ثُمَّ ‏ ‏يُصَلِّي الرَّكْعَتَيْنِ بَيْنَ النِّدَاءِ وَالْإِقَامَةِ مِنْ صَلَاةِ الصُّبْحِ ‏","","",""],[24384,24384,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُفْيَانَ ‏ ‏يُحَدِّثُ قَالَ حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْأَقْمَرِ ‏ ‏عَنْ ‏ ‏أَبِي حُذَيْفَةَ ‏ ‏وَكَانَ مِنْ أَصْحَابِ ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَكَانَ ‏ ‏طَلْحَةُ ‏ ‏يُحَدِّثُ عَنْهُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏حَكَيْتُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا فَقَالَ ‏ ‏مَا يَسُرُّنِي أَنِّي حَكَيْتُ رَجُلًا وَأَنَّ لِي كَذَا وَكَذَا قَالَتْ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏صَفِيَّةَ ‏ ‏امْرَأَةٌ وَقَالَ بِيَدِهِ كَأَنَّهُ ‏ ‏يَعْنِي قَصِيرَةً فَقَالَ لَقَدْ مَزَجْتِ بِكَلِمَةٍ لَوْ مُزِجَ بِهَا مَاءُ الْبَحْرِ مَزَجَتْ ‏","","",""],[24385,24385,"","","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَجَدْتُ هَذَا الْحَدِيثَ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏لَمْ يَسْمَعْ ‏ ‏عَبْدُ اللَّهِ ‏ ‏هَذَا الْحَدِيثَ ‏ ‏يَعْنِي حَدِيثَ ‏ ‏جَابِرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا خَرَجَ مِنْ ‏ ‏الْخَلَاءِ ‏ ‏تَوَضَّأَ ‏","","",""],[24386,24386,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخُصُّ مِنْ الْأَيَّامِ شَيْئًا قَالَتْ ‏ ‏لَا كَانَ عَمَلُهُ ‏ ‏دِيمَةً ‏ ‏وَأَيُّكُمْ كَانَ يُطِيقُ مَا كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُطِيقُ ‏","","",""],[24387,24387,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا حِضْتُ يَأْمُرُنِي ‏ ‏فَأَتَّزِرُ ‏ ‏ثُمَّ ‏ ‏يُبَاشِرُنِي ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَغْتَسِلُ أَنَا وَهُوَ مِنْ إِنَاءٍ وَاحِدٍ وَنَحْنُ جُنُبَانِ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُخْرِجُ رَأْسَهُ إِلَيَّ وَهُوَ ‏ ‏مُعْتَكِفٌ ‏ ‏فَأَغْسِلُهُ وَأَنَا حَائِضٌ ‏","","",""],[24388,24388,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا ‏ ‏اشْتَرَتْ ‏ ‏بَرِيرَةَ ‏ ‏قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَشْتَرِي ‏ ‏بَرِيرَةَ ‏ ‏وَأَشْتَرِطُ ‏ ‏لَهُمْ ‏ ‏الْوَلَاءَ ‏ ‏قَالَ اشْتَرِي فَإِنَّمَا ‏ ‏الْوَلَاءُ ‏ ‏لِمَنْ وَلِيَ النِّعْمَةَ ‏ ‏أَوْ لِمَنْ أَعْتَقَ ‏","","",""],[24389,24389,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏وَالْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَفْتِلُ ‏ ‏قَلَائِدَ ‏ ‏هَدْيِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَنَمًا ثُمَّ لَا يُحْرِمُ ‏","","",""],[24390,24390,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَصُمْ الْعَشْرَ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَأَسْنَدَهُ ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏","","",""],[24391,24391,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏وَوَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكْثِرُ أَنْ يَقُولَ فِي سُجُودِهِ وَرُكُوعِهِ ‏ ‏سُبْحَانَكَ رَبَّنَا وَبِحَمْدِكَ اللَّهُمَّ اغْفِرْ لِي ‏ ‏يَتَأَوَّلُ ‏ ‏الْقُرْآنَ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏اللَّهُمَّ وَبِحَمْدِكَ ‏","","",""],[24392,24392,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏مَوْلًى لِعَائِشَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا رَأَيْتُ فَرْجَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَطُّ ‏","","",""],[24393,24393,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَخْرُجُ إِلَى صَلَاةِ الصُّبْحِ وَرَأْسُهُ يَقْطُرُ فَيُصْبِحُ صَائِمًا ‏","","",""],[24394,24394,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا رَأَى ‏ ‏نَاشِئًا ‏ ‏مِنْ أُفُقٍ مِنْ آفَاقِ السَّمَاءِ تَرَكَ عَمَلَهُ وَإِنْ كَانَ فِي صَلَاتِهِ ثُمَّ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا فِيهِ فَإِنْ كَشَفَهُ اللَّهُ حَمِدَ اللَّهَ وَإِنْ مَطَرَتْ قَالَ اللَّهُمَّ ‏ ‏صَيِّبًا ‏ ‏نَافِعًا ‏","","",""],[24395,24395,"","","‏ ‏حَدَّثَنَا ‏ ‏عبدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَخَّصَ فِي ‏ ‏الرُّقْيَةِ ‏ ‏مِنْ كُلِّ ذِي ‏ ‏حُمَةٍ ‏","","",""],[24396,24396,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَنَسٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْبِتْعِ ‏ ‏فَقَالَ ‏ ‏كُلُّ شَرَابٍ أَسْكَرَ فَهُوَ حَرَامٌ ‏","","",""],[24397,24397,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورِ ابْنِ صَفِيَّةَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَضَعُ رَأْسَهُ فِي حِجْرِهَا وَيَقْرَأُ الْقُرْآنَ وَهِيَ حَائِضٌ ‏","","",""],[24398,24398,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ يَعْنِي ابْنَ أَبِي خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَامِرٌ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏قَالَ قُلْتُ إِنَّ هَاهُنَا رَجُلًا يَبْعَثُ بِهَدْيِهِ إِلَى ‏ ‏الْكَعْبَةِ ‏ ‏فَيَأْمُرُ الَّذِي يَسُوقُهَا لَهُ مِنْ مَعْلَمٍ قَدْ أَمَرَهُ فَيُقَلِّدُهَا وَلَا يَزَالُ مُحْرِمًا حَتَّى يُحِلَّ النَّاسُ قَالَ فَسَمِعْتُ تَصْفِيقَ يَدَيْهَا مِنْ وَرَاءِ الْحِجَابِ ‏ ‏لَقَدْ كُنْتُ ‏ ‏أَفْتِلُ ‏ ‏قَلَائِدَ ‏ ‏الْهَدْيِ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَبْعَثُ ‏ ‏بِهَدْيِهِ ‏ ‏فَمَا يَحْرُمُ عَلَيْهِ شَيْءٌ مِمَّا يَحْرُمُ عَلَى الرَّجُلِ مِنْ أَهْلِهِ حَتَّى يَرْجِعَ النَّاسُ ‏","","",""],[24399,24399,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ يَعْنِي ابْنَ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏إِنَّمَا ‏ ‏نَزَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُحَصَّبَ ‏ ‏لِيَكُونَ أَسْمَحَ لِخُرُوجِهِ وَلَيْسَ بِسُنَّةٍ فَمَنْ شَاءَ نَزَلَهُ وَمَنْ شَاءَ لَمْ يَنْزِلْهُ ‏","","",""],[24400,24400,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏لَمَّا نَزَلَتْ الْآيَاتُ الْأَوَاخِرُ مِنْ سُورَةِ ‏ ‏الْبَقَرَةِ ‏ ‏قَرَأَهُنَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى النَّاسِ وَحَرَّمَ ‏ ‏التِّجَارَةَ فِي الْخَمْرِ ‏","","",""]];
